const guideCallbacks=new Map();let guideCallbackId=0;const guideKnownActions={"eduScreen++;renderEadLesson()":function(event){eduScreen++;renderEadLesson()},
"eadFinalReview()":function(event){eadFinalReview()},
"friendlyPortalStep++;renderFriendlyPortal()":function(event){friendlyPortalStep++;renderFriendlyPortal()},
"mapStage(2)":function(event){mapStage(2)},
"startEadLesson()":function(event){startEadLesson()},
"friendlyPortalStep=0;renderFriendlyPortal()":function(event){friendlyPortalStep=0;renderFriendlyPortal()},
"mapStage(0)":function(event){mapStage(0)},
"completeVisualFlow()":function(event){completeVisualFlow()},
"flowOpen(4)":function(event){flowOpen(4)},
"flowOpen(3)":function(event){flowOpen(3)},
"flowOpen(5)":function(event){flowOpen(5)},
"finishContinuousFlow()":function(event){finishContinuousFlow()},
"flowOpen(1)":function(event){flowOpen(1)},
"flowOpen(2)":function(event){flowOpen(2)},
"captureAsylumDraft();asylumEvidence()":function(event){captureAsylumDraft();asylumEvidence()},
"showAsylumDocumentChecklist()":function(event){showAsylumDocumentChecklist()}};
function guideActionByText(text){if(guideKnownActions[text])return guideKnownActions[text];const m=String(text).match(/^startVisual\('([a-z]+)'\)$/);if(m)return function(){startVisual(m[1])};throw new Error('Unknown guide action: '+text)}
function guideBind(event,callback){const id='g'+(++guideCallbackId);guideCallbacks.set(id,callback);return 'data-guide-'+event+'="'+id+'"'}
for(const kind of ['click','change','input','keydown'])document.addEventListener(kind,function(event){const el=event.target.closest('[data-guide-'+kind+']');if(!el)return;const callback=guideCallbacks.get(el.getAttribute('data-guide-'+kind));if(callback)callback.call(el,event)});
guideCallbacks.set("initial0",function(event){if(confirm('¿Borrar el progreso de esta guía en este navegador?')){localStorage.removeItem('immigra-progress');location.reload()}});
const app=document.querySelector('#app');let saved={};try{saved=JSON.parse(localStorage.getItem('immigra-progress')||'{}')}catch{};let active='',idx=0;
const links={account:'https://www.uscis.gov/file-online/how-to-create-a-uscis-online-account',address:'https://www.uscis.gov/addresschange',court:'https://www.justice.gov/eoir/update-respondent-or-alien-information',foia:'https://first.uscis.gov/',fees:'https://www.uscis.gov/feecalculator',asap:'https://asaptogether.org/es/guias-practicas/',irap:'https://support.iraplegalinfo.org/hc/en-us/articles/45334351447572-How-do-I-set-up-a-USCIS-Online-Account'};
const guides={account:{icon:'💻',title:'Mi cuenta myUSCIS',desc:'Crea tu acceso y aprende a protegerlo.',source:links.account,docs:['Correo electrónico personal accesible','Acceso al método de verificación elegido','Un lugar seguro para guardar la recuperación de acceso'],steps:[['Abre el portal oficial','Entra desde la página oficial de USCIS. Busca la opción para crear una cuenta personal. No compartas la cuenta con otra persona.','Create an account','https://my.uscis.gov/'],['Confirma tu correo','Escribe tu correo en el portal oficial y abre el mensaje de confirmación. Si no llega, revisa spam y las opciones de reenvío.','Confirm Email',links.account],['Configura tu seguridad','Crea una contraseña conforme a los requisitos actuales del portal. Configura el método de verificación y conserva las opciones de recuperación en un lugar privado.','Verification code',links.account],['Reconoce tu panel','Identifica tus casos y las acciones disponibles. Algunas opciones dependen del expediente y del tipo de cuenta. Guarda tu acceso; esta guía no se conecta a tu cuenta.','My Account',links.account]]},address:{icon:'🏠',title:'Dirección con USCIS',desc:'Prepara el cambio y revisa cada caso pendiente.',source:links.address,docs:['Dirección anterior y nueva, incluido apartamento y ZIP','Fecha de mudanza','Recibos de cada solicitud pendiente'],steps:[['Identifica todas las agencias','USCIS, corte/BIA e ICE tienen procesos diferentes. Si tienes obligaciones ante varias agencias, revisa cada ruta. Cambiar la dirección postal no actualiza USCIS.','USCIS / EOIR / ICE',links.address],['Reúne tus datos','Ten a mano direcciones completas y los recibos de tus solicitudes pendientes. El número de recibo y el A-Number son identificadores diferentes.','Receipt number',links.address],['Usa el cambio de dirección','Consulta la página oficial y las instrucciones para tu población. La mayoría puede usar su cuenta. USCIS indica generalmente notificar dentro de 10 días de mudarse; existen procedimientos específicos.','Change of Address',links.address],['Revisa y guarda la constancia','Verifica apartamento y ZIP. Incluye los recibos pendientes donde lo solicite el sistema. Presenta personalmente y guarda la confirmación oficial. Marcar este paso no presenta el cambio.','Confirmation',links.address]]},court:{icon:'🏛️',title:'Dirección en corte / BIA',desc:'Distingue la corte de la junta de apelaciones.',source:links.court,docs:['A-Number de cada persona','Información del tribunal o BIA','Dirección y datos de contacto actualizados'],steps:[['Elige el organismo correcto','Si el caso está en corte, revisa EOIR-33/IC. Si está ante la BIA, revisa EOIR-33/BIA. EOIR indica actualizar dentro de cinco días laborables.','EOIR-33/IC / EOIR-33/BIA',links.court],['Abre Respondent Access','Selecciona el formulario correspondiente en el portal oficial. La plataforma indica completar las respuestas en inglés.','Change Contact Info','https://respondentaccess.eoir.justice.gov/en/forms/'],['Revisa los datos de cada persona','Prepara un formulario por persona afectada con un caso pendiente. Sigue todas las instrucciones de presentación y notificación que aparezcan en el formulario.','Alien Registration Number',links.court],['Presenta y conserva copia','Finaliza el envío y descarga el documento o constancia. Actualizar dirección no solicita por sí mismo un traslado de corte. Si necesitas traslado, busca orientación.','Submit / Download',links.court]]},foia:{icon:'🔎',title:'Solicita tus registros · FOIA',desc:'Identifica la agencia y prepara tu solicitud.',source:links.foia,docs:['Información de identidad solicitada por el portal','Descripción de los registros y periodo que buscas','Datos del expediente que conozcas, sin inventarlos'],steps:[['¿Quién tiene los registros?','Para registros en poder de USCIS, consulta FIRST. Para documentos de corte, consulta EOIR. Para registros de otra agencia, usa su procedimiento. Una solicitud a una agencia no obtiene necesariamente todo tu historial.','USCIS / EOIR / otras agencias',links.foia],['Entra al sistema oficial','FIRST es el sistema de registros FOIA de USCIS. Revisa la página oficial antes de iniciar y distingue solicitar tus registros de solicitar registros de otra persona.','FIRST · FOIA Immigration Records System',links.foia],['Describe lo que necesitas','Indica documentos específicos y periodos cuando los conozcas. Usa la información real disponible. Sigue las instrucciones de identidad, consentimiento y cualquier aviso de cargos.','Records requested',links.foia],['Guarda y consulta el seguimiento','Revisa antes de presentar. Conserva el número FOIA y consulta las respuestas en el sistema. Solicitar registros no presenta una solicitud migratoria ni suspende sus plazos.','FOIA tracking number',links.foia]]}};
function esc(x){return x.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function ext(url,label){return `<a class="btn" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`}function count(k){return guides[k].steps.filter((_,i)=>saved[k+'-'+i]).length}function persist(){localStorage.setItem('immigra-progress',JSON.stringify(saved))}
function home(){app.innerHTML=("<section class=\"selectorhero\"><div><span class=\"pill\" style=\"color:#06336f\">🧩 TU RUTA PERSONALIZADA</span><h2>¿Qué formularios debes considerar?</h2><p>Elige tu trámite. Explora sus derivaciones y prepara tu lista.</p></div><button class=\"yellow\" "+guideBind("click",(function(){return function(event){selector()}})())+">Encontrar mi ruta →</button></section><h2>Elige dónde comenzar</h2><p class=\"muted\">Puedes explorar cualquier guía. Dentro de cada una avanzarás paso a paso.</p><article class=\"card visualintro\" "+guideBind("click",(function(){return function(event){captureGallery()}})())+" style=\"cursor:pointer;margin-bottom:24px\"><img src=\"assets/myuscis-register.jpg\" alt=\"Captura real de myUSCIS\"><div><span class=\"tag\">CAPTURAS REALES · TOCA LOS PUNTOS</span><h2>Aprende sobre la pantalla real →</h2><p>Descubre qué significa cada opción, con explicaciones sobre la imagen.</p></div></article><div class=\"grid\">"+(Object.entries(guides).map(([k,g])=>("<article class=\"card\"><div class=\"icon\">"+(g.icon)+"</div><span class=\"tag\">GUÍA INICIAL · "+(g.steps.length)+" PASOS</span><h2>"+(g.title)+"</h2><p>"+(g.desc)+"</p><p>"+(count(k))+" de "+(g.steps.length)+" pasos recorridos</p><div class=\"progress\"><span style=\"width:"+(count(k)/g.steps.length*100)+"%\"></span></div><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(arg7){return function(event){openGuide(''+arg7+'')}})(k))+">"+(count(k)?'Continuar':'Comenzar')+" →</button></div></article>")).join(''))+"<article class=\"card gold\"><div class=\"icon\">🏆</div><h2>Revisión con IA</h2><p>Función prevista para el plan anual. Revisará posibles faltantes e inconsistencias; no determinará elegibilidad.</p><strong>Pendiente de integración</strong><p>No se reciben documentos en este prototipo.</p></article><article class=\"card\"><div class=\"icon\">📂</div><h2>Formularios por proceso</h2><p>Ciudadanía · Peticiones familiares · Tarjeta de residencia · TPS · Viajes. Consulta listas iniciales y enlaces oficiales.</p><button "+guideBind("click",(function(){return function(event){processCatalog()}})())+">Explorar procesos →</button></article></div>")}
function openGuide(k){active=k;idx=guides[k].steps.findIndex((_,i)=>!saved[k+'-'+i]);if(idx<0)idx=0;render()}
function render(){const g=guides[active],s=g.steps[idx];app.innerHTML=("<button "+guideBind("click",(function(){return function(event){home()}})())+">← Todos los módulos</button>"+(contextBar(g.title,s[0],idx+1,g.steps.length))+"<div class=\"workspace\"><aside><div class=\"map\">"+(g.steps.map((s,i)=>("<div class=\"node\"><span>"+(saved[active+'-'+i]?'✓':i+1)+" · "+(s[0])+"</span><button aria-label=\"Abrir paso "+(i+1)+"\" "+guideBind("click",(function(arg3){return function(event){idx=arg3;render()}})(i))+" "+(i>0&&!saved[active+'-'+(i-1)]?'disabled':'')+">→</button></div>")).join(''))+"</div><small>Avance de lectura; no confirma presentación.</small></aside><article class=\"card step\"><span class=\"tag\">"+(g.title.toUpperCase())+" · PASO "+(idx+1)+" DE "+(g.steps.length)+"</span><h2>"+(s[0])+"</h2><p>"+(s[1])+"</p>"+(stepCapture(active,idx))+"<details><summary>Fuente oficial y vigencia</summary>"+(ext(s[3],'Abrir fuente oficial'))+"</details><details><summary>📁 Documentos y datos que debes considerar</summary>"+(g.docs.map((d,i)=>("<label class=\"check\"><input type=\"checkbox\" "+(saved[active+'-doc-'+i]?'checked':'')+" "+guideBind("change",(function(arg1){return function(event){saved[active+'-doc-'+arg1+'']=this.checked;persist()}})(i))+">"+(d)+"</label>")).join(''))+"</details><details><summary>Mi pantalla es diferente</summary><p>Detente y consulta las instrucciones oficiales. No elijas una respuesta solo para avanzar. Puedes volver a la guía o consultar a un profesional.</p>"+(ext(g.source,'Consultar instrucciones'))+"</details><p class=\"muted\">Consulta: 04/11/2026 · Orientación inicial. Verifica vigencia antes de actuar.</p><div class=\"actions\"><button "+guideBind("click",(function(){return function(event){idx=Math.max(0,idx-1);render()}})())+" "+(idx===0?'disabled':'')+">← Anterior</button><button class=\"primary\" "+guideBind("click",(function(){return function(event){complete()}})())+">"+(idx===g.steps.length-1?'Completar recorrido ✓':'Completé este paso →')+"</button></div></article></div>")}
function complete(){saved[active+'-'+idx]=true;persist();if(idx<guides[active].steps.length-1){idx++;render()}else{app.innerHTML=("<article class=\"card\"><div class=\"icon\">✅</div><h2>Recorrido completado</h2><p>Terminaste la guía. Esto no significa que hayas presentado el trámite ni que tu información sea correcta. Revisa la confirmación del portal oficial y busca ayuda profesional cuando sea necesario.</p><button "+guideBind("click",(function(){return function(event){home()}})())+">Volver al mapa</button></article>")}}
const terms=[['A-Number','Identificador de registro de extranjero; no es el número de recibo.','Busca etiquetas como A-Number, USCIS# o Alien Registration Number en tus avisos o documentos migratorios. No todos los documentos lo muestran.'],['Receipt number','Identifica una solicitud o petición concreta.','Normalmente aparece como Receipt Number en el aviso de recibo de USCIS.'],['USCIS Online Account Number','Identificador de la cuenta en línea, diferente del recibo y del A-Number.','Revisa tu perfil y los avisos de acceso de USCIS, si te fue asignado.'],['I-94','Registro de llegada/salida y datos de admisión o parole.','Consulta el portal oficial de CBP en i94.cbp.dhs.gov o tu documento en papel, si corresponde.'],['RFE','Solicitud de evidencia adicional.','Busca el aviso Request for Evidence y lee su fecha límite e instrucciones completas.'],['FOIA','Procedimiento para solicitar acceso a registros de una agencia, sujeto a excepciones.','Identifica primero qué agencia conserva el documento que buscas.'],['I-797','Familia de avisos de USCIS. Su significado depende del tipo y contenido.','Lee Notice Type y el texto completo. Un recibo no equivale a aprobación.'],['Cover letter','Carta que presenta y organiza un paquete. No es requisito universal.','Puedes preparar un borrador en Carta e índice; no sustituye formularios ni evidencias.'],['Proof of service','Constancia de notificación o entrega a la otra parte cuando se requiere.','Sigue las instrucciones del formulario o tribunal correspondiente.']];
function glossary(){app.innerHTML=("<h2>📖 Entiende la palabra. Encuentra el dato.</h2><input type=\"search\" placeholder=\"Buscar: A-Number, recibo, FOIA…\" aria-label=\"Buscar término\" "+guideBind("input",(function(){return function(event){filterTerms(this.value)}})())+"><div id=\"terms\"></div>");filterTerms('')}function filterTerms(q){document.querySelector('#terms').innerHTML=terms.filter(t=>t.join(' ').toLowerCase().includes(q.toLowerCase())).map(t=>`<details><summary>${t[0]}</summary><p>${t[1]}</p><p><strong>¿Dónde buscarlo?</strong> ${t[2]}</p>${termVisual(t[0])}</details>`).join('')||'<p>No encontramos ese término.</p>'}
function packet(){app.innerHTML=("<article class=\"card\"><span class=\"tag\">BORRADOR · HERRAMIENTA DE ORGANIZACIÓN</span><h2>📑 Tu carta de presentación e índice</h2><p>Plantilla general sin datos personales. Adáptala al trámite y a las instrucciones oficiales. No determina qué documentos debes presentar ni cuál es la dirección correcta.</p><textarea id=\"draft\" aria-label=\"Borrador editable\">[DATE]\n[RECIPIENT / VERIFIED FILING ADDRESS]\n\nRE: [FORM / REQUEST TYPE]\nApplicant: [NAME]\n\nDear Sir or Madam:\nEnclosed please find my [FORM / REQUEST] and the supporting documents listed below.\n\nDOCUMENT INDEX\n1. [Required form, signed as applicable]\n2. [Payment documentation, if applicable]\n3. [Identity document, if required]\n4. [Evidence supporting the specific eligibility category]\n5. [Certified English translations, if applicable]\n6. [Additional documents required by current instructions]\n\nSincerely,\n[NAME / SIGNATURE AS APPLICABLE]"+(Object.keys(saved).filter(k=>k.startsWith('form-')&&saved[k]).length?'\n\nFORMS SELECTED FOR REVIEW (NOT CONFIRMED REQUIREMENTS)\n'+Object.keys(saved).filter(k=>k.startsWith('form-')&&saved[k]).map(k=>k.slice(5)).join('\n'):'')+"</textarea><p>Elimina las líneas que no correspondan. No envíes los marcadores entre corchetes. Verifica formularios, firmas, edición, tarifas, destino y anexos antes de presentar.</p><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(){return function(event){downloadDraft()}})())+">Descargar borrador .txt</button><button "+guideBind("click",(function(){return function(event){window.print()}})())+">Imprimir</button>"+(ext(links.fees,'Verificar tarifas'))+"</div></article>")}function downloadDraft(){const u=URL.createObjectURL(new Blob([document.querySelector('#draft').value],{type:'text/plain;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download='borrador-carta-indice.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function resources(){app.innerHTML=`<h2>🔗 Fuentes y material visual</h2><p>Abre las guías originales para ver sus capturas y videos actualizados. No se han reproducido imágenes de terceros.</p><div class="grid"><article class="card sources"><h2>Fuentes oficiales</h2>${Object.entries(links).filter(([k])=>!['asap','irap'].includes(k)).map(([k,u])=>ext(u,({account:'Crear cuenta USCIS',address:'Dirección USCIS',court:'Dirección EOIR',foia:'FOIA · FIRST',fees:'Calculadora de tarifas'})[k])).join('')}${ext('https://foia.eoir.justice.gov/app/Home.aspx','FOIA de EOIR')}</article><article class="card sources"><h2>ASAP · En español</h2>${ext(links.asap,'Guías prácticas')}${ext('https://asaptogether.org/es/cambio-de-direccion/','Cambio de dirección')}${ext('https://asaptogether.org/es/solicitud-de-asilo-en-linea/','Asilo en línea')}${ext('https://asaptogether.org/es/solicitud-de-permiso-de-trabajo-en-linea/','Permiso de trabajo')}<p>ASAP permite enlazar sus recursos, pero no copiarlos en línea en inglés o español.</p>${ext('https://asaptogether.org/es/politica-para-compartir-recursos/','Política de uso')}</article><article class="card sources"><h2>Capturas y ayuda profesional</h2>${ext(links.irap,'IRAP · Cuenta con capturas')}${ext('https://www.justice.gov/eoir/recognized-organizations-and-accredited-representatives-roster-state-and-city','Representantes acreditados')}${ext('https://www.uscis.gov/avoid-scams/find-legal-services','Encontrar servicios legales')}<p>Las interfaces cambian. Confirma cada paso en el portal original.</p></article></div>`}home();

let route={};
function selector(){route={};app.innerHTML=("<span class=\"tag\">MISIÓN 1 · IDENTIFICA TU TRÁMITE</span><h2>🧩 ¿Qué quieres preparar?</h2><p>Este selector organiza información educativa. Tus respuestas no determinan elegibilidad ni sustituyen una revisión legal.</p><div class=\"choices\"><button "+guideBind("click",(function(){return function(event){adjustStart()}})())+">🪪 Ajuste de estatus<br><small>Ruta familiar, asilo aprobado u otra categoría</small></button><button "+guideBind("click",(function(){return function(event){basicRoute('asylum')}})())+">🛡️ Solicitud de asilo<br><small>Distingue USCIS de corte</small></button><button "+guideBind("click",(function(){return function(event){basicRoute('ead')}})())+">💼 Permiso de trabajo<br><small>Identifica la categoría antes de elegir</small></button><button "+guideBind("click",(function(){return function(event){openGuide('foia')}})())+">🔎 Solicitar registros · FOIA<br><small>Elige la agencia que tiene tus documentos</small></button><button "+guideBind("click",(function(){return function(event){openGuide('address')}})())+">🏠 Dirección USCIS<br><small>Cuenta y casos pendientes</small></button><button "+guideBind("click",(function(){return function(event){openGuide('court')}})())+">🏛️ Dirección corte / BIA<br><small>EOIR-33 según el organismo</small></button></div>")}
function adjustStart(){app.innerHTML=("<button "+guideBind("click",(function(){return function(event){selector()}})())+">← Trámites</button><h2>🪪 ¿En qué se basa tu ajuste?</h2><div class=\"routebar\"><span>1. Trámite ✓</span><span>2. Categoría</span><span>3. Formularios</span><span>4. Documentos</span></div><div class=\"choices\"><button "+guideBind("click",(function(){return function(event){familyQuestions()}})())+">👨‍👩‍👧 Petición familiar</button><button "+guideBind("click",(function(){return function(event){asyleeResult()}})())+">🛡️ Asilo aprobado</button><button "+guideBind("click",(function(){return function(event){otherAdjust()}})())+">💼 Empleo u otra categoría</button><button "+guideBind("click",(function(){return function(event){otherAdjust()}})())+">❓ No estoy seguro</button></div>")}
function familyQuestions(){app.innerHTML=("<button "+guideBind("click",(function(){return function(event){adjustStart()}})())+">← Categorías</button><article class=\"card\"><h2>👨‍👩‍👧 Ruta familiar</h2><p>Primero identifica tu relación y el estado de la petición. Esta selección no verifica admisión, disponibilidad de visa, impedimentos ni jurisdicción.</p><label>Relación con el peticionario<select id=\"relationship\"><option value=\"spouse\">Cónyuge</option><option value=\"parent\">Padre o madre</option><option value=\"child\">Hijo o hija / hijastro</option><option value=\"other\">Otra relación / necesito confirmarlo</option></select></label><p><label>Estado de la I-130<select id=\"petition\"><option value=\"new\">No presentada / no sé</option><option value=\"pending\">Pendiente</option><option value=\"approved\">Aprobada</option></select></label></p><label>¿Tienes proceso en corte?<select id=\"jurisdiction\"><option value=\"unknown\">No sé</option><option value=\"no\">No</option><option value=\"yes\">Sí</option></select></label><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(){return function(event){familyResult()}})())+">Ver formularios a considerar →</button></div></article>")}
function formCard(n,title,status,why,docs,url){return ("<article class=\"card\"><span class=\"formtag\">"+(status)+"</span><h3>📄 "+(n)+"</h3><strong>"+(title)+"</strong><p>"+(why)+"</p><details><summary>Documentos que debes considerar</summary><ul>"+(docs.map(x=>`<li>${x}</li>`).join(''))+"</ul></details><label class=\"check\"><input type=\"checkbox\" "+(saved['form-'+n]?'checked':'')+" "+guideBind("change",(function(arg6){return function(event){saved['form-'+arg6+'']=this.checked;persist()}})(n))+">Añadir a mi lista de revisión</label>"+(ext(url,'Formulario e instrucciones'))+"</article>")}
function resultShell(title,intro,cards){app.innerHTML=("<button "+guideBind("click",(function(){return function(event){selector()}})())+">← Cambiar mi ruta</button><h2>"+(title)+"</h2><div class=\"routebar\"><span>Trámite ✓</span><span>Categoría ✓</span><span>↓ Formularios relacionados</span><span>↓ Documentos por formulario</span><span>↓ Carta e índice</span></div><div class=\"notice\">"+(intro)+" Esta lista es inicial y puede ser incompleta. Consulta a un abogado o representante acreditado antes de decidir tu elegibilidad o resolver impedimentos.</div><div class=\"formgrid\" style=\"margin-top:24px\">"+(cards)+"</div><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(){return function(event){packet()}})())+">Preparar carta e índice →</button>"+(ext(links.fees,'Comprobar tarifas'))+"</div><p class=\"muted\">Fuentes oficiales por tarjeta · Consulta 4 de noviembre de 2026. No se muestran importes ni direcciones fijas: confírmalos para tu categoría y método de presentación.</p>")}
function familyResult(){const rel=document.querySelector('#relationship').value,pet=document.querySelector('#petition').value,j=document.querySelector('#jurisdiction').value;let c=formCard('I-485','Solicitud de ajuste','SOLICITUD PRINCIPAL','Solo si puedes ajustar bajo la categoría aplicable. Esta guía no confirma que puedas presentar.', ['Identidad y nacimiento','Admisión o parole cuando corresponda','Prueba de la categoría y avisos pertinentes'],'https://www.uscis.gov/i-485');c+=formCard('I-130','Petición familiar',pet==='new'?'POR CONFIRMAR':'YA PRESENTADA SEGÚN TU RESPUESTA',pet==='new'?'Revisa si debe presentarse y cuándo. No toda categoría permite presentación conjunta.':'Considera el recibo o aprobación como evidencia; no presentes otra petición automáticamente.',['Prueba del estatus del peticionario','Documentos que acreditan el parentesco'],'https://www.uscis.gov/i-130');if(rel==='spouse')c+=formCard('I-130A','Información del cónyuge','ASOCIADO A PETICIÓN CONYUGAL','Revisa este suplemento al preparar una I-130 para cónyuge. Si ya fue presentada, verifica lo que se incluyó.',['Historial de domicilios y empleo','Datos biográficos solicitados'],'https://www.uscis.gov/i-130');c+=formCard('I-864 / I-864EZ','Patrocinio económico','GENERALMENTE · REVISAR EXCEPCIONES','Determina qué versión corresponde y si existe una exención. Un patrocinador conjunto y un miembro del hogar tienen reglas diferentes.',['Documentación fiscal e ingresos','Estatus y domicilio del patrocinador','Activos si se utilizan'],'https://www.uscis.gov/i-864');c+=formCard('I-864A','Contrato con miembro del hogar','CONDICIONAL','Revisar si se usarán ingresos o activos de un miembro del hogar bajo las reglas aplicables. No equivale al I-864 de un patrocinador conjunto.',['Relación y residencia del miembro','Prueba de ingresos o activos utilizados'],'https://www.uscis.gov/i-864a');c+=formCard('I-693','Examen médico y vacunas','CUANDO SEA REQUERIDO','Lo completa un médico civil autorizado. Sigue las reglas actuales de presentación y manejo del examen.',['Identificación','Historial de vacunas y datos médicos para el médico'],'https://www.uscis.gov/i-693');c+=formCard('I-765','Autorización de empleo','OPCIONAL · SEGÚN CATEGORÍA','Revisa la categoría aplicable al ajuste pendiente y si necesitas solicitar este beneficio.',['Recibo de I-485 cuando corresponda','Identidad y EAD previo si aplica'],'https://www.uscis.gov/i-765');c+=formCard('I-131','Documento de viaje','OPCIONAL · CONSULTAR ANTES DE VIAJAR','No es autorización para viajar por sí solo. Presentarlo o recibirlo no resuelve todos los riesgos de salida o reingreso.',['Documentación de la categoría','Identidad y propósito según instrucciones'],'https://www.uscis.gov/i-131');resultShell('Tu ruta · Ajuste familiar',j==='no'?'Antes de presentar, verifica requisitos de ajuste y disponibilidad de visa.':'Jurisdicción por confirmar: tienes o podrías tener proceso en corte. Busca orientación antes de decidir dónde presentar.',c)}
function asyleeResult(){resultShell('Tu ruta · Asilo aprobado','Esta ruta corresponde a personas con asilo concedido; asilo pendiente es una situación distinta. No se aplica automáticamente el paquete familiar ni I-864.',formCard('I-485','Ajuste como asilado','SEGÚN REQUISITOS DE ESTA CATEGORÍA','Verifica presencia física, estatus y demás requisitos actuales.',['Prueba de concesión de asilo','Evidencia de presencia física','Identidad y documentos civiles pertinentes'],'https://www.uscis.gov/green-card/green-card-eligibility/green-card-for-asylees')+formCard('I-693','Examen y vacunas','SI CORRESPONDE','Revisa si necesitas examen completo o parcial según tus antecedentes.',['Vacunas e historial para el médico civil'],'https://www.uscis.gov/i-693')+formCard('Otros formularios','Revisión individual','CONDICIONAL','Exenciones de tarifas o causales de inadmisibilidad requieren revisar sus requisitos. No añadas formularios sin confirmar que aplican.',['Avisos y antecedentes relevantes para revisión profesional'],'https://www.uscis.gov/i-485'))}
function otherAdjust(){resultShell('Categoría por confirmar','El ajuste puede basarse en empleo, programas especiales u otras categorías. Necesitamos una ruta revisada para tu categoría antes de recomendar un paquete.',formCard('I-485','Revisa la categoría correcta','ORIENTACIÓN INICIAL','No uses el paquete familiar como lista universal. Revisa las instrucciones oficiales y consulta a un profesional.',['Prueba de tu categoría','Avisos de peticiones relacionadas'],'https://www.uscis.gov/i-485'))}
function basicRoute(k){if(k==='asylum'){app.innerHTML=("<h2>🛡️ Asilo · Selecciona la agencia</h2><p>No todos pueden presentar en línea ante USCIS. Confirma jurisdicción, plazos y requisitos con orientación profesional.</p><div class=\"choices\"><button "+guideBind("click",(function(){return function(event){asylumResult(false)}})())+">USCIS · Por confirmar</button><button "+guideBind("click",(function(){return function(event){asylumResult(true)}})())+">Corte / no estoy seguro</button></div>")}else{resultShell('💼 Permiso de trabajo · I-765','El formulario depende de una categoría de elegibilidad. Tener un caso migratorio no implica automáticamente poder solicitar permiso.',formCard('I-765','Solicitud de autorización de empleo','CONFIRMA LA CATEGORÍA','Identifica la base: asilo pendiente, ajuste pendiente, TPS u otra. Revisa requisitos, plazos y solicitud inicial, renovación o reemplazo.',['Prueba de la categoría','Identidad','EAD anterior si corresponde','Fotos y demás anexos según instrucciones'],'https://www.uscis.gov/i-765'))}}
function asylumResult(court){resultShell('🛡️ Asilo · Formularios y evidencias',court?'Confirma la jurisdicción con un profesional. No presentes en myUSCIS solo para avanzar.':'Verifica en la página oficial si puedes presentar ante USCIS y por qué método.',formCard('I-589','Asilo y protección relacionada','SOLICITUD · SEGÚN JURISDICCIÓN','Revisa plazos, requisitos, instrucciones y familiares que puedan incluirse.',['Identidad y documentos de entrada disponibles','Relato veraz y cronológico','Pruebas de hechos y temor cuando estén disponibles','Documentos familiares y traducciones cuando correspondan'],'https://www.uscis.gov/i-589'))}

const termResources={
'A-Number':['https://www.uscis.gov/forms/filing-guidance','Consultar orientación de USCIS'],
'Receipt number':['https://egov.uscis.gov/','Consultar estatus con el recibo'],
'USCIS Online Account Number':['https://my.uscis.gov/','Abrir myUSCIS'],
'I-94':['https://i94.cbp.dhs.gov/','Consultar I-94 en CBP'],
'RFE':['https://www.uscis.gov/forms/filing-guidance','Consultar instrucciones de presentación'],
'FOIA':['https://first.uscis.gov/','Abrir FIRST'],
'I-797':['https://www.uscis.gov/forms/filing-guidance/form-i-797-types-and-functions','Tipos de aviso I-797'],
'Cover letter':['https://www.uscis.gov/forms/filing-guidance','Orientación para organizar la presentación'],
'Proof of service':['https://www.justice.gov/eoir/reference-materials/ic','Manual de práctica de corte']};
function termVisual(term){const i=terms.findIndex(t=>t[0]===term),r=termResources[term];return `<figure style="margin:18px 0"><img src="assets/glossary-${i}.svg" alt="Guía ilustrativa para localizar ${term}; busca la etiqueta resaltada" style="width:100%;max-width:900px;border-radius:18px"><figcaption>Ilustración propia con datos ficticios. La posición puede variar en tu documento.</figcaption></figure><div class="actions">${ext('assets/glossary-'+i+'.svg','Ampliar imagen')}${r?ext(r[0],r[1]):''}</div>`}
const moreProcesses={
'family':['👨‍👩‍👧 Petición familiar','I-130','Petición de familiar','Principal según la relación; no concede residencia por sí sola.',['Estatus del peticionario','Prueba de parentesco','Documentación matrimonial si corresponde'],'https://www.uscis.gov/i-130'],
'citizenship':['🇺🇸 Naturalización','N-400','Solicitud de naturalización','Verifica requisitos y documentos de tu base de naturalización.',['Tarjeta de residencia','Historial de viajes, domicilios y empleo','Documentos matrimoniales o antecedentes cuando correspondan'],'https://www.uscis.gov/n-400'],
'card':['🪪 Renovar o reemplazar tarjeta','I-90','Renovación o reemplazo','No reemplaza el proceso para eliminar condiciones de residencia.',['Copia de tarjeta o prueba de estatus disponible','Evidencia del motivo de reemplazo'],'https://www.uscis.gov/i-90'],
'conditions':['💍 Eliminar condiciones por matrimonio','I-751','Petición para eliminar condiciones','Distingue petición conjunta y posibles exenciones. Revisa plazos y busca ayuda individual.',['Tarjeta condicional','Evidencias de matrimonio de buena fe','Documentos adicionales según la base de presentación'],'https://www.uscis.gov/i-751'],
'tps':['🛡️ TPS','I-821','Solicitud de TPS','Confirma primero que exista designación y periodo de solicitud aplicable a tu país.',['Identidad y nacionalidad','Residencia y presencia física exigidas','Otros documentos según programa'],'https://www.uscis.gov/i-821'],
'travel':['✈️ Documentos de viaje','I-131','Solicitud de documento de viaje','El tipo de documento depende de tu estatus y finalidad. Consulta antes de viajar.',['Identidad y estatus','Prueba de la base del documento solicitado'],'https://www.uscis.gov/i-131']};
function processCatalog(){app.innerHTML=("<h2>📚 Formularios por proceso</h2><p>Selecciona el proceso para ver formularios principales y relacionados. Lista inicial educativa, no determinación de elegibilidad.</p><div class=\"choices\"><button "+guideBind("click",(function(){return function(event){adjustStart()}})())+">🪪 Ajuste de estatus</button><button "+guideBind("click",(function(){return function(event){basicRoute('asylum')}})())+">🛡️ Asilo</button><button "+guideBind("click",(function(){return function(event){basicRoute('ead')}})())+">💼 Permiso de trabajo</button>"+(Object.entries(moreProcesses).map(([k,v])=>("<button "+guideBind("click",(function(arg0){return function(event){processResult(''+arg0+'')}})(k))+">"+(v[0])+"</button>")).join(''))+"<button "+guideBind("click",(function(){return function(event){openGuide('foia')}})())+">🔎 FOIA</button><button "+guideBind("click",(function(){return function(event){openGuide('court')}})())+">🏛️ Dirección corte / BIA</button><button "+guideBind("click",(function(){return function(event){openGuide('address')}})())+">🏠 Dirección USCIS</button></div>")}
function processResult(k){const v=moreProcesses[k];let cards=formCard(v[1],v[2],'FORMULARIO PRINCIPAL · SEGÚN REQUISITOS',v[3],v[4],v[5]);if(k==='family')cards+=formCard('I-130A','Información del cónyuge','SI LA PETICIÓN ES PARA CÓNYUGE','Revisa el suplemento correspondiente y las instrucciones actuales.',['Historial de domicilios y empleo','Datos biográficos'],'https://www.uscis.gov/i-130');if(k==='tps')cards+=formCard('I-765','Autorización de empleo','SI CORRESPONDE','Revisa la categoría y las reglas vigentes de solicitud y pago.',['Prueba de categoría TPS','Identidad y permiso anterior si aplica'],'https://www.uscis.gov/i-765');resultShell(v[0],v[3],cards)}

const realScreens=[
{img:'myuscis-home',title:'Reconoce el portal oficial myUSCIS',source:'https://my.uscis.gov/',points:[[84,10,'Sign In','Aquí aparece el menú de acceso. No escribas credenciales en esta guía. Abre personalmente el portal oficial cuando estés listo.'],[30,9,'Identidad del sitio','Comprueba el dominio my.uscis.gov y la identificación de USCIS. Una captura no sustituye verificar la dirección del navegador.']]},
{img:'myuscis-register',title:'Encuentra la opción para crear tu cuenta',source:'https://my.uscis.gov/',points:[[21,50,'Sign up','Esta opción inicia el registro. Necesitarás un correo al que tengas acceso. La creación de cuenta se realiza en USCIS, no aquí.'],[76,84,'Find a doctor','Este acceso sirve para buscar médicos civiles autorizados. El I-693 debe prepararse conforme a las instrucciones oficiales.']]},
{img:'first-home',title:'Distingue FOIA de un trámite migratorio',source:'https://first.uscis.gov/#/',points:[[34,87,'Sign In or Create an Account','Esta sección explica el acceso para administrar solicitudes de registros. FOIA no presenta asilo, ajuste ni permiso de trabajo.'],[64,87,'Check FOIA/PA Request Status','Esta sección orienta sobre seguimiento. La pantalla de seguimiento actual puede pedir iniciar sesión para ver tus solicitudes.'],[43,21,'FIRST','Estás viendo el sistema de registros de USCIS. Los registros de otras agencias pueden requerir solicitudes separadas.']]},
{img:'first-status',title:'Aprende a consultar el seguimiento FOIA',source:'https://first.uscis.gov/#/check-status',points:[[26,36,'View My Requests','La pantalla explica cómo acceder a las solicitudes y consultar información. Los tiempos visibles son una fotografía de la fecha de captura y pueden cambiar.']]}
];let screenIndex=0;
let captureContext='';
function screenFigure(i){const c=realScreens[i];return `<figure style="margin:0"><div class="capturebox"><img src="assets/${c.img}.jpg" alt="Captura real: ${c.title}">${c.points.map((p,j)=>("<button class=\"hotspot\" style=\"left:"+(p[0])+"%;top:"+(p[1])+"%\" aria-label=\"Explicar "+(p[2])+"\" "+guideBind("click",(function(arg3,arg4){return function(event){showPoint(arg3,arg4)}})(i,j))+">"+(j+1)+"</button>")).join('')}<div class="capturecaption">${captureContext || c.title} · Captura real · 04/11/2026</div></div><figcaption class="muted">Toca un punto numerado. Las anotaciones son de IMMIGRA; el portal puede cambiar.</figcaption></figure><div id="pointExplain" class="explain" aria-live="polite">Toca el punto 1 para comenzar.</div><details><summary>Ver procedencia de esta captura</summary><a href="${c.source}" target="_blank" rel="noopener">${c.source}</a><p>Sin datos personales. Capturada de una página pública oficial. No implica respaldo de la agencia.</p></details>`}
function showPoint(i,j){let p=realScreens[i].points[j];document.querySelector('#pointExplain').innerHTML=`<strong>${j+1}. ${p[2]}</strong><br>${p[3]}`}
function captureGallery(){tourCatalog()}
function stepCapture(k,i){captureContext=guides[k].title+' · Paso '+(i+1)+' de '+guides[k].steps.length+' · '+guides[k].steps[i][0];if(k==='account'&&i===0)return screenFigure(1);if(k==='foia'&&i===1)return screenFigure(2);if(k==='foia'&&i===3)return screenFigure(3);return `<div class="notice"><strong>Captura específica pendiente de verificación.</strong><p>Esta etapa aún no tiene una captura real incorporada. Consulta las instrucciones antes de actuar.</p></div>`}

function contextBar(process,stage,step,total){return `<section class="contextbar" aria-label="Ubicación en la guía"><small>ESTÁS EN ESTE PROCESO</small><h2>${process}</h2><div class="stage"><strong>${stage}</strong><span class="stepbadge">Paso ${step} de ${total}</span></div><div class="progress"><span style="width:${step/total*100}%"></span></div><p>Guía educativa · El progreso no confirma presentación ni aprobación.</p></section>`}
const tourData={
account:{title:'Mi cuenta myUSCIS',icon:'💻',form:'Cuenta personal',source:links.account,docs:guides.account.docs},
address:{title:'Cambio de dirección USCIS',icon:'🏠',form:'E-COA / AR-11 según instrucciones',source:links.address,docs:guides.address.docs},
court:{title:'Cambio de dirección corte / BIA',icon:'🏛️',form:'EOIR-33/IC o EOIR-33/BIA',source:links.court,docs:guides.court.docs},
foia:{title:'Solicitar registros · FOIA USCIS',icon:'🔎',form:'Solicitud en FIRST',source:links.foia,docs:guides.foia.docs},
adjust:{title:'Ajuste de estatus',icon:'🪪',form:'I-485 y formularios relacionados según categoría',source:'https://www.uscis.gov/i-485',docs:['Identidad y documentos civiles','Prueba de la categoría de ajuste','Documentos migratorios y avisos','Examen médico y patrocinio económico cuando correspondan']},
asylum:{title:'Solicitud de asilo',icon:'🛡️',form:'I-589',source:'https://www.uscis.gov/i-589',docs:['Identidad y datos de entrada disponibles','Cronología veraz de hechos','Evidencias de hechos y temor cuando estén disponibles','Documentación familiar y traducciones cuando correspondan']},
ead:{title:'Permiso de trabajo',icon:'💼',form:'I-765',source:'https://www.uscis.gov/i-765',docs:['Prueba de la categoría de elegibilidad','Documento de identidad','EAD anterior si corresponde','Otros anexos que requieran las instrucciones']},
...Object.fromEntries(Object.entries(moreProcesses).map(([k,v])=>[k,{title:v[0],icon:'📄',form:v[1],source:v[5],docs:v[4]}]))
};
let tourKey='account',tourStep=0;const tourStages=['Identifica tu ruta','Reúne documentos','Ubica el formulario o portal','Prepara tus respuestas','Organiza y revisa','Presenta y conserva constancia'];
function tourCatalog(){captureContext='';app.innerHTML=`<h2>🖼 Aprende en pantalla · Elige tu proceso</h2><p>Cada recorrido identifica el proceso, la etapa y el paso. Las capturas reales se muestran donde están verificadas; las demás se señalan como pendientes.</p><div class="grid">${Object.entries(tourData).map(([k,t])=>("<article class=\"card\"><div class=\"icon\">"+(t.icon)+"</div><h2>"+(t.title)+"</h2><span class=\"tag\">"+(t.form)+" · 6 ETAPAS</span><p>"+(['account','foia'].includes(k)?'Incluye capturas públicas reales; pantallas internas pendientes.':'Recorrido inicial; capturas específicas pendientes.')+"</p><button class=\"primary\" "+guideBind("click",(function(arg4){return function(event){startTour(''+arg4+'')}})(k))+">Recorrer paso a paso →</button></article>")).join('')}</div>`}
function startTour(k){tourKey=k;tourStep=0;renderTour()}
function tourText(k,i){const t=tourData[k];if(i===0){if(k==='adjust')return 'Distingue ajuste familiar, asilo aprobado u otra categoría. La lista de formularios cambia según la base. Confirma jurisdicción y elegibilidad antes de presentar.';if(k==='asylum')return 'Confirma si tu caso corresponde a USCIS o corte y qué plazos y requisitos se aplican. No elijas presentación en línea sin confirmar la ruta.';if(k==='ead')return 'Identifica la categoría de elegibilidad y si es solicitud inicial, renovación o reemplazo. Tener un caso pendiente no implica automáticamente poder solicitar un permiso.';if(k==='tps')return 'Confirma designación vigente, nacionalidad, fechas y periodo de solicitud aplicable. Esta guía no confirma que el programa esté disponible para tu país.';return 'Identifica el propósito del proceso y revisa sus instrucciones. Si tienes dudas sobre tu situación, consulta a un abogado o representante acreditado.'}if(i===1)return 'Revisa los documentos siguientes. La lista es inicial: los requisitos completos dependen de tu categoría y de las instrucciones vigentes.';if(i===2)return 'Formulario o sistema: '+t.form+'. Antes de completar, confirma la edición aceptada y el método de presentación en la fuente oficial.';if(i===3)return 'Usa únicamente información verdadera y comprobada. Distingue nombre legal, A-Number, recibo y número de cuenta. No inventes respuestas para continuar. Las pantallas internas específicas aún requieren verificación.';if(i===4)return 'Contrasta formularios, datos, firmas, traducciones y anexos. Si presentas un paquete, prepara una carta e índice adaptados. Revisa tarifas y destino en las instrucciones actuales.';return 'Presenta personalmente en el sistema o destino correcto. Guarda copia completa, comprobante y números de seguimiento. Completar esta guía no presenta la solicitud ni suspende plazos.'}
function renderTour(){const t=tourData[tourKey],i=tourStep;captureContext=t.title+' · Paso '+(i+1)+' de 6 · '+tourStages[i];let pic=null;if(tourKey==='account'&&i===2)pic=1;if(tourKey==='foia'&&i===2)pic=2;if(tourKey==='foia'&&i===5)pic=3;app.innerHTML=("<button "+guideBind("click",(function(){return function(event){tourCatalog()}})())+">← Cambiar proceso</button>"+(contextBar(t.title,tourStages[i],i+1,6))+"<div class=\"stageindex\">"+(tourStages.map((x,j)=>`<span class="${j===i?'current':''}">${j+1}. ${x}</span>`).join(''))+"</div><article class=\"tourstage\"><span class=\"tag\">"+(t.form)+"</span><h2>"+(tourStages[i])+"</h2><p>"+(tourText(tourKey,i))+"</p>"+(pic!==null?screenFigure(pic):`<div class="notice"><strong>Captura de esta etapa pendiente.</strong><p>No se ha verificado una pantalla real para este paso de ${t.title}. El texto es orientación inicial; no es un tutorial completo de todos los campos.</p></div>`)+(i===1?t.docs.map((d,j)=>("<label class=\"check\"><input type=\"checkbox\" "+(saved['tour-'+tourKey+'-doc-'+j]?'checked':'')+" "+guideBind("change",(function(arg1,arg2){return function(event){saved['tour-'+arg1+'-doc-'+arg2+'']=this.checked;persist()}})(tourKey,j))+">"+(d)+"</label>")).join(''):'')+(i===3?("<details><summary>📖 Ayuda para encontrar tus datos</summary><p>Consulta el glosario visual para distinguir los identificadores y encontrar los datos en tus documentos.</p><button "+guideBind("click",(function(){return function(event){glossary()}})())+">Abrir glosario</button></details>"):'')+(i===4?("<details><summary>📑 Preparar carta e índice</summary><p>Herramienta opcional de organización; adáptala a las instrucciones de tu trámite.</p><button "+guideBind("click",(function(){return function(event){packet()}})())+">Abrir borrador</button></details>"):'')+(i===0&&tourKey==='adjust'?("<button "+guideBind("click",(function(){return function(event){adjustStart()}})())+">Explorar derivaciones de ajuste</button>"):'')+"<details><summary>Fuente oficial de "+(t.title)+"</summary>"+(ext(t.source,'Consultar instrucciones oficiales'))+"</details><div class=\"gallerynav\"><button "+guideBind("click",(function(){return function(event){tourStep--;renderTour()}})())+" "+(i===0?'disabled':'')+">← Paso anterior</button><strong>"+(i+1)+" / 6</strong><button class=\"primary\" "+guideBind("click",(function(){return function(event){nextTour()}})())+">"+(i===5?'Terminar recorrido ✓':'Continuar al paso '+(i+2)+' →')+"</button></div></article>")}
function nextTour(){saved['tour-'+tourKey+'-'+tourStep]=true;persist();if(tourStep<5){tourStep++;renderTour()}else{app.innerHTML=((contextBar(tourData[tourKey].title,'Recorrido inicial completado',6,6))+"<article class=\"card\"><h2>Revisa antes de actuar</h2><p>Has recorrido las seis etapas informativas. Las capturas pendientes y la revisión de requisitos deben completarse antes de considerar esta una guía integral. Tu trámite no ha sido presentado por esta página.</p><button "+guideBind("click",(function(){return function(event){tourCatalog()}})())+">Volver a procesos</button></article>")}}

let mapProcess='',mapCategory='';
const originalGlossary=glossary,originalPacket=packet,originalSelector=selector,originalRenderTour=renderTour;
function processPicker(){mapProcess='';mapCategory='';document.querySelector('.hero h1').innerHTML='Elige tu proceso.<br><span>Descubre tu camino.</span>';app.innerHTML=("<section class=\"processfilter\"><span class=\"tag\">PRIMERO · SELECCIONA TU PROCESO</span><h2>¿Qué necesitas hacer?</h2><p>Elige una opción para ver únicamente su mapa de pasos, documentos y herramientas.</p><label for=\"processChoice\">Mi proceso</label><select id=\"processChoice\" "+guideBind("change",(function(){return function(event){processFilterChanged(this.value)}})())+"><option value=\"\">Selecciona un proceso…</option>"+(Object.entries(tourData).map(([k,t])=>`<option value="${k}">${t.title}</option>`).join(''))+"</select><div id=\"subfilter\"></div><button id=\"openMap\" class=\"primary\" disabled "+guideBind("click",(function(){return function(event){chooseProcess()}})())+">Ver mi mapa →</button></section>")}
function processFilterChanged(k){const sub=document.querySelector('#subfilter');sub.innerHTML=k==='adjust'?`<label for="categoryChoice">¿En qué se basa el ajuste?</label><select id="categoryChoice"><option value="family">Petición familiar</option><option value="asylee">Asilo aprobado</option><option value="other">Otra categoría / no estoy seguro</option></select>`:k==='asylum'?`<label for="categoryChoice">¿Ante qué organismo?</label><select id="categoryChoice"><option value="uscis">USCIS · por confirmar</option><option value="court">Corte de inmigración</option><option value="unknown">No estoy seguro</option></select>`:'';document.querySelector('#openMap').disabled=!k}
function chooseProcess(){mapProcess=document.querySelector('#processChoice').value;mapCategory=document.querySelector('#categoryChoice')?.value||'';mapView()}
function branchTitle(){if(mapProcess==='adjust')return {family:'Petición familiar',asylee:'Asilo aprobado',other:'Categoría por confirmar'}[mapCategory];if(mapProcess==='asylum')return {uscis:'USCIS · por confirmar',court:'Corte de inmigración',unknown:'Jurisdicción por confirmar'}[mapCategory];return ''}
function mapView(){const t=tourData[mapProcess];if(!t){processPicker();return}document.querySelector('.hero h1').innerHTML='Tu proceso, conectado.<br><span>Un paso a la vez.</span>';let branch='';if(mapProcess==='adjust'){branch=`<div class="mapline"></div><div class="mapbranches">${[['family','👨‍👩‍👧 Petición familiar','I-130 / I-130A y patrocinio según corresponda'],['asylee','🛡️ Asilo aprobado','Documentos de concesión y ruta propia'],['other','🧭 Otra categoría','Confirmar requisitos y buscar orientación']].map(([k,n,d])=>("<button class=\"mapbranch "+(mapCategory===k?'selected':'')+"\" "+guideBind("click",(function(arg1){return function(event){mapCategory=''+arg1+'';mapView()}})(k))+">"+(n)+"<small>"+(d)+"</small></button>")).join('')}</div>`}if(mapProcess==='asylum'){branch=`<div class="mapline"></div><div class="mapbranches">${[['uscis','USCIS','Confirmar posibilidad de presentación'],['court','Corte','Instrucciones de EOIR'],['unknown','No estoy seguro','Consultar antes de elegir']].map(([k,n,d])=>("<button class=\"mapbranch "+(mapCategory===k?'selected':'')+"\" "+guideBind("click",(function(arg1){return function(event){mapCategory=''+arg1+'';mapView()}})(k))+">"+(n)+"<small>"+(d)+"</small></button>")).join('')}</div>`}
const stages=[['🧭','Confirma tu ruta','Ubica el organismo y los requisitos que debes revisar.'],['🧩','Formularios de este proceso','Principal, condicionales y opcionales, según tu ruta.'],['📁','Documentos y datos','Lista de preparación y glosario visual para encontrar los datos.'],['🖼️','Aprende en pantalla','Recorre las imágenes verificadas y sus explicaciones.'],['📑','Organiza tu expediente','Carta e índice como herramientas de organización.'],['🔎','Revisión antes de presentar','Firmas, versiones, pagos, destino y constancias.']];app.innerHTML=("<div class=\"maphead\"><div><span class=\"tag\">TU MAPA · "+(t.form)+"</span><h2>"+(t.title)+(branchTitle()?' · '+branchTitle():'')+"</h2></div><button "+guideBind("click",(function(){return function(event){processPicker()}})())+">Cambiar proceso</button></div><p class=\"maplegend\">Las etapas visitadas se marcan en verde. Sigue las conexiones de arriba hacia abajo. Toca una etapa para abrir su contenido. Las derivaciones dependen de tu proceso.</p><section class=\"mapcanvas\" aria-label=\"Mapa conectado de "+(t.title)+"\"><div class=\"maproot\"><small style=\"color:#bfe3ff\">PROCESO SELECCIONADO</small><h2>"+(t.icon)+" "+(t.title)+"</h2><span>"+(branchTitle()||t.form)+"</span></div>"+(branch)+(stages.map(([icon,n,d],i)=>("<div class=\"mapline\" aria-hidden=\"true\"></div><button class=\"mapnode "+(saved['map-'+mapProcess+'-'+i]?'done':'')+"\" "+guideBind("click",(function(arg1){return function(event){mapStage(arg1)}})(i))+"><span class=\"n\">"+(i+1)+"</span><span>"+(icon)+"</span><strong>"+(n)+"</strong><small>"+(d)+"</small></button>")).join(''))+"</section><div class=\"notice\">Esta ruta organiza información educativa. No confirma elegibilidad. Recomendamos buscar ayuda de un abogado de inmigración o representante acreditado.</div>")}
function mapReturn(label){if(!mapProcess)return;app.insertAdjacentHTML('afterbegin',("<div class=\"toolreturn\"><span>"+(tourData[mapProcess].title)+(branchTitle()?' · '+branchTitle():'')+" / "+(label)+"</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Volver a mi mapa</button></div>"))}
function mapStage(i){saved['map-'+mapProcess+'-'+i]=true;persist();const t=tourData[mapProcess];if(i===0){tourKey=mapProcess;tourStep=0;renderTour();return}if(i===1){if(mapProcess==='adjust'){if(mapCategory==='family')familyQuestions();else if(mapCategory==='asylee')asyleeResult();else otherAdjust()}else if(mapProcess==='asylum')asylumResult(mapCategory!=='uscis');else if(mapProcess==='ead')basicRoute('ead');else if(moreProcesses[mapProcess])processResult(mapProcess);else{app.innerHTML=`${contextBar(t.title,'Formularios o sistema correspondiente',2,6)}<article class="card"><h2>${t.form}</h2><p>Verifica el procedimiento de ${t.title} en las instrucciones oficiales. No necesitas seleccionar formularios de otros procesos.</p>${ext(t.source,'Consultar instrucciones')}</article>`}mapReturn('Formularios');return}if(i===2){app.innerHTML=((contextBar(t.title,'Documentos y datos',3,6))+"<article class=\"card\"><h2>📁 Prepara lo que corresponde a tu proceso</h2>"+(t.docs.map((d,j)=>("<label class=\"check\"><input type=\"checkbox\" "+(saved['tour-'+mapProcess+'-doc-'+j]?'checked':'')+" "+guideBind("change",(function(arg1,arg2){return function(event){saved['tour-'+arg1+'-doc-'+arg2+'']=this.checked;persist()}})(mapProcess,j))+">"+(d)+"</label>")).join(''))+"<details><summary>📖 ¿Qué significa y dónde lo encuentro?</summary><p>Abre el glosario visual para reconocer A-Number, recibo, I-94 y otros datos en tus documentos.</p><button "+guideBind("click",(function(){return function(event){glossary()}})())+">Consultar glosario visual</button></details></article>");mapReturn('Documentos');return}if(i===3){captureContext=t.title+' · Paso 4 de 6 · Aprende en pantalla';const pic=mapProcess==='account'?1:mapProcess==='foia'?2:null;app.innerHTML=`${contextBar(t.title,'Aprende en pantalla',4,6)}${pic!==null?screenFigure(pic):'<article class="card"><h2>Capturas específicas pendientes</h2><p>Este proceso todavía no tiene una secuencia real de pantallas verificada. No uses las imágenes de otro proceso como instrucciones.</p></article>'}`;mapReturn('Aprende en pantalla');return}if(i===4){packet();return}app.innerHTML=`${contextBar(t.title,'Revisión antes de presentar',6,6)}<article class="card"><h2>🔎 Revisa antes de actuar</h2><p>Confirma cada punto con las instrucciones de ${t.title}.</p>${['La ruta y el organismo corresponden a mi situación','Verifiqué formularios, edición aceptada y firmas','Revisé anexos y traducciones aplicables','Confirmé tarifa, forma de pago y destino actuales','Guardaré copia completa y constancia oficial'].map(x=>`<label class="check"><input type="checkbox">${x}</label>`).join('')}<p>Completar esta lista no confirma elegibilidad ni presentación. Busca orientación profesional si hay dudas.</p>${ext(t.source,'Ver instrucciones oficiales')}</article>`;mapReturn('Revisión final')}
glossary=function(){originalGlossary();mapReturn('Glosario visual')};packet=function(){originalPacket();if(mapProcess)app.insertAdjacentHTML('afterbegin',contextBar(tourData[mapProcess].title,'Organiza tu expediente',5,6));mapReturn('Carta e índice')};renderTour=function(){originalRenderTour();mapReturn('Paso a paso')};home=processPicker;captureGallery=function(){if(mapProcess){tourKey=mapProcess;tourStep=2;renderTour()}else processPicker()};selector=function(){if(mapProcess)mapStage(1);else processPicker()};tourCatalog=processPicker;
const originalResultShell=resultShell;resultShell=function(...args){originalResultShell(...args);if(mapProcess){app.insertAdjacentHTML('afterbegin',contextBar(tourData[mapProcess].title,'Formularios de este proceso',2,6));mapReturn('Formularios')}};
processPicker();

