let visualKey='',visualPage=0,visualSpot=0,visualFocus=false;
function startVisual(k){visualKey=k;visualPage=0;visualSpot=0;visualFocus=false;renderVisual()}
function renderVisual(){const g=visualGuides[visualKey],s=g.slides[visualPage],p=s.spots[visualSpot],c=s.crop;let vb=c;if(visualFocus){const pad=30;vb=[Math.max(c[0],p[0]-pad),Math.max(c[1],p[1]-pad),Math.min(c[2],p[2]+pad*2),Math.min(c[3],p[3]+pad*2)]}app.innerHTML=("<div class=\"toolreturn\"><span>"+(g.name)+" / Aprende en pantalla</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Volver a mi mapa</button></div>"+(contextBar(g.name+(branchTitle()?' · '+branchTitle():''),'Aprende en pantalla',4,6))+"<div class=\"visual-subhead\"><div><span class=\"tag\">"+(g.form)+" · PÁGINA "+(s.page)+" DEL DOCUMENTO</span><h2>"+(s.title)+"</h2></div><strong>Pantalla "+(visualPage+1)+" de "+(g.slides.length)+"</strong></div>"+(g.draft?'<div class="draft-notice"><strong>BORRADOR PÚBLICO · NO PRESENTAR</strong><p>Esta referencia permite reconocer los bloques del documento. No confirma el contenido final ni la edición aceptada. Descarga el formulario vigente desde USCIS antes de preparar tu solicitud.</p></div>':'')+"<div class=\"visual-workspace\"><figure class=\"real-document\"><svg viewBox=\""+(vb.join(' '))+"\" role=\"img\" aria-label=\""+(g.form)+", página "+(s.page)+": "+(s.title)+"\"><image href=\"assets/"+(s.image)+"\" width=\"1363\" height=\"936\"/><rect x=\""+(p[0])+"\" y=\""+(p[1])+"\" width=\""+(p[2])+"\" height=\""+(p[3])+"\" rx=\"8\" fill=\"#ffe02c\" fill-opacity=\".16\" stroke=\"#0784ff\" stroke-width=\"4\"/>"+(s.spots.map((q,j)=>("<g role=\"button\" tabindex=\"0\" aria-label=\"Explicar "+(q[4])+"\" "+guideBind("click",(function(arg1){return function(event){selectVisualSpot(arg1)}})(j))+" "+guideBind("keydown",(function(arg2){return function(event){if(event.key==='Enter'||event.key===' '){event.preventDefault();selectVisualSpot(arg2)}}})(j))+"><circle cx=\""+(q[0]+15)+"\" cy=\""+(q[1]+15)+"\" r=\"16\" fill=\""+(j===visualSpot?'#ffd329':'#0776e9')+"\" stroke=\"white\" stroke-width=\"3\"/><text x=\""+(q[0]+15)+"\" y=\""+(q[1]+21)+"\" text-anchor=\"middle\" font-size=\"17\" font-family=\"Arial\" font-weight=\"bold\" fill=\""+(j===visualSpot?'#062d62':'white')+"\">"+(j+1)+"</text></g>")).join(''))+"</svg><figcaption>Imagen real de formulario en blanco · Edición "+(g.edition)+". Las marcas interactivas son de IMMIGRA.</figcaption></figure><aside class=\"visual-explanation\"><span class=\"formtag\">ZONA "+(visualSpot+1)+" DE "+(s.spots.length)+"</span><h2>"+(p[4])+"</h2><p aria-live=\"polite\">"+(p[5])+"</p><button class=\"primary\" "+guideBind("click",(function(){return function(event){nextVisualSpot()}})())+">"+(visualSpot<s.spots.length-1?'Entendido · Siguiente zona →':visualPage<g.slides.length-1?'Ir a la siguiente pantalla →':'Terminar recorrido visual ✓')+"</button><button "+guideBind("click",(function(){return function(event){visualFocus=!visualFocus;renderVisual()}})())+">"+(visualFocus?'Ver página completa':'Ampliar zona resaltada')+"</button><details><summary>Qué contiene este recorrido</summary><p>Explica zonas seleccionadas. No cubre todos los campos ni confirma elegibilidad. Verifica edición, instrucciones y requisitos oficiales antes de presentar.</p></details><details><summary>Procedencia y formulario vigente</summary><p>Documento creado por USCIS; copia pública consultada en OMB.report, sitio independiente. No es una afiliación con USCIS.</p><a href=\""+(g.source)+"\" target=\"_blank\" rel=\"noopener\">Ver copia de referencia</a><br><a href=\""+(g.official)+"\" target=\"_blank\" rel=\"noopener\">Consultar formulario vigente en USCIS</a></details></aside></div><div class=\"gallerynav\"><button "+guideBind("click",(function(){return function(event){visualPage--;visualSpot=0;visualFocus=false;renderVisual()}})())+" "+(visualPage===0?'disabled':'')+">← Pantalla anterior</button><span>"+(g.form)+" · Pantalla "+(visualPage+1)+"/"+(g.slides.length)+"</span><button "+guideBind("click",(function(){return function(event){visualPage++;visualSpot=0;visualFocus=false;renderVisual()}})())+" "+(visualPage===g.slides.length-1?'disabled':'')+">Pantalla siguiente →</button></div>");document.querySelector('.contextbar')?.scrollIntoView({block:'start'})}
function selectVisualSpot(i){visualSpot=i;renderVisual()}
function nextVisualSpot(){if(visualSpot<visualGuides[visualKey].slides[visualPage].spots.length-1){visualSpot++;renderVisual()}else if(visualPage<visualGuides[visualKey].slides.length-1){visualPage++;visualSpot=0;visualFocus=false;renderVisual()}else{saved['visual-'+visualKey]=true;persist();mapView()}}
const beforeVisualMapStage=mapStage;mapStage=function(i){if(i===3&&visualGuides[mapProcess]){saved['map-'+mapProcess+'-'+i]=true;persist();startVisual(mapProcess);return}beforeVisualMapStage(i)};

