let eadProfile={base:'',kind:'',method:''},eduScreen=0;
const oldProcessFilter=processFilterChanged,oldChooseProcess=chooseProcess,oldBranchTitle=branchTitle;
processFilterChanged=function(k){oldProcessFilter(k);if(k==='ead'){document.querySelector('#subfilter').innerHTML=("<label for=\"eadBase\">¿En qué se basa tu permiso?</label><select id=\"eadBase\" "+guideBind("change",(function(){return function(event){eadFilterChange()}})())+"><option value=\"\">Selecciona tu base…</option><option value=\"c8\">Asilo pendiente · (c)(8)</option><option value=\"c9\">Cierto ajuste pendiente bajo INA 245 · (c)(9)</option><option value=\"other\">Otra categoría / no sé cuál corresponde</option></select><label for=\"eadKind\">¿Qué necesitas solicitar?</label><select id=\"eadKind\" "+guideBind("change",(function(){return function(event){eadFilterChange()}})())+"><option value=\"\">Selecciona…</option><option value=\"initial\">Solicitud inicial</option><option value=\"renewal\">Renovación</option><option value=\"replacement\">Reemplazo</option></select><label for=\"eadMethod\">¿Cómo quieres prepararlo?</label><select id=\"eadMethod\" "+guideBind("change",(function(){return function(event){eadFilterChange()}})())+"><option value=\"online\">En línea · si mi categoría admite el recorrido guiado</option><option value=\"paper\">Formulario en papel</option><option value=\"pdf\">Presentación de PDF · solo si mi categoría está habilitada</option></select><p class=\"muted\">Asilo ya aprobado no es asilo pendiente. Un ajuste como asilado tampoco convierte automáticamente tu categoría en (c)(9).</p>");document.querySelector('#openMap').disabled=true}};
function eadFilterChange(){document.querySelector('#openMap').disabled=!document.querySelector('#eadBase').value||!document.querySelector('#eadKind').value}
chooseProcess=function(){if(document.querySelector('#processChoice').value==='ead')eadProfile={base:document.querySelector('#eadBase').value,kind:document.querySelector('#eadKind').value,method:document.querySelector('#eadMethod').value};oldChooseProcess()};
function eadLabel(){return `${eadProfile.base==='c8'?'(c)(8) · Asilo pendiente':eadProfile.base==='c9'?'(c)(9) · Ajuste pendiente':'Categoría por confirmar'} · ${{initial:'Inicial',renewal:'Renovación',replacement:'Reemplazo'}[eadProfile.kind]||'Tipo por confirmar'}`}
branchTitle=function(){return mapProcess==='ead'?eadLabel():oldBranchTitle()};
function doc(title,when,examples,where,check,missing,source){return{title,when,examples,where,check,missing,source}}
function eadDocuments(){const a=[doc('Identidad o permiso anterior','Según historial y requisitos de la categoría',['EAD más reciente: anverso y reverso, si fue emitido.','Si no hubo EAD: pasaporte con foto, nombre y nacimiento, o identificación gubernamental admitida por las instrucciones.'],'Revisa tu pasaporte, tarjeta y documentos de identidad.','Copia legible, bordes completos y ambas caras cuando corresponda.','No uses un acta sin foto como sustituto universal de identidad. Consulta las alternativas de las instrucciones.',eduSources.check),doc('Fotografía para I-765','Según método de presentación',['En papel: dos fotografías tipo pasaporte iguales y recientes, conforme a las instrucciones.','En el formulario guiado: archivo de foto que cumpla las especificaciones de carga.'],'Estudio fotográfico o foto que cumpla los requisitos oficiales.','Tamaño 2 × 2 pulgadas; rostro visible, fondo claro y sin filtros. No confundas una foto del pasaporte con la fotografía tipo pasaporte solicitada.','Haz una nueva foto si no cumple; no alteres tu rostro con IA o filtros.',eduSources.photo),doc('Traducciones','Si un anexo está en otro idioma',['Documento completo en su idioma original.','Traducción íntegra al inglés y certificación del traductor sobre competencia y exactitud.'],'Conserva el documento y su traducción juntos.','Incluye todas las páginas y sellos legibles; no basta traducir una parte.','Consigue una traducción completa antes de presentar el anexo que la necesita.',eduSources.check)];
if(eadProfile.base==='c8')a.unshift(doc('Prueba de que presentaste asilo','Ruta de asilo pendiente',['Aviso de recibo I-589 de USCIS; revisa número y fecha de recepción.','Si presentaste en corte: copia con constancia de presentación u otra prueba admitida.'],'Tus avisos de USCIS o copia del expediente presentado en corte.','No confundas la fecha en que firmaste con la fecha de presentación. Una NTA por sí sola no prueba que presentaste I-589.','Busca el recibo o constancia. Si hubo denegación, apelación, cierre o traslado, requiere revisar la situación antes de usar esta ruta.',eduSources.ead));
if(eadProfile.base==='c9')a.unshift(doc('Prueba de I-485 pendiente','Si I-765 se presenta separado del ajuste',['Aviso I-797 de recibo de I-485, u otra evidencia admitida de que sigue pendiente.','Si se presentan juntos: prepara el I-765 conforme a las instrucciones de presentación conjunta.'],'Avisos de tu I-485 y copia del paquete de ajuste.','Un recibo o aprobación de I-130 por sí solo no demuestra que I-485 esté pendiente.','No inventes un número. Revisa presentación conjunta o solicita copia del aviso si el ajuste ya fue recibido.',eduSources.address));
if(eadProfile.base!=='c9')a.push(doc('Registro de entrada o documento de viaje','Según instrucciones y documentos disponibles',['I-94 electrónico impreso; I-94 en papel por ambas caras.','Pasaporte u otro documento de viaje cuando las instrucciones lo permitan.'],'Portal oficial de CBP o documentos recibidos al ingresar.','Distingue número I-94, clase de admisión y fecha autorizada.','Revisa las alternativas de evidencia; no escribas datos aproximados para llenar el espacio.',eduSources.check));
if(eadProfile.kind!=='initial')a.push(doc('EAD y motivo de renovación o reemplazo','Si ya hubo un permiso',['Copia de las dos caras del permiso anterior.','Para reemplazo: identifica si fue pérdida, robo, daño o error y sigue el procedimiento correspondiente.'],'Tarjeta anterior y copias conservadas.','Verifica categoría, vigencia y nombre. No todos los errores se corrigen con una nueva I-765.','Busca una copia; si el error fue de USCIS, revisa su procedimiento específico antes de pagar.',eduSources.ead));
a.push(doc('Antecedentes o cambios que afecten la solicitud','Solo si aplican a tu situación',['Si las instrucciones exigen antecedentes: reportes y resoluciones certificadas de corte pertinentes.','Documento legal de cambio de nombre si necesitas explicar diferencias.'],'Tribunal, agencia o autoridad que emitió el documento.','Una explicación personal no reemplaza automáticamente un registro certificado exigido.','Busca orientación individual antes de presentar si hay arrestos, condenas, órdenes o dudas sobre tu categoría.',eduSources.ead));return a}
const evidenceDetails={
asylum:[doc('Identidad y entradas','Según documentos disponibles',['Pasaporte y documentos de entrada; I-94 si existe.'],'Documentos personales y CBP.','Nombres, fechas y páginas legibles.','Explica documentos no disponibles; no fabriques copias.','https://www.uscis.gov/i-589'),doc('Familiares incluidos','Si incluyes cónyuge o hijos elegibles',['Acta de matrimonio o nacimiento para acreditar vínculo.','Divorcios o defunciones pertinentes.'],'Registro civil o copias oficiales disponibles.','El vínculo y los nombres deben coincidir.','Revisa evidencia secundaria admitida y explica ausencia.','https://www.uscis.gov/i-589'),doc('Hechos y pruebas del caso','Según lo ocurrido realmente',['Mensajes de amenazas con fecha, emisor y contexto.','Denuncias, documentos médicos, fotos o declaraciones de testigos con conocimiento directo.'],'Tus archivos originales, institución emisora o testigos.','Relaciona cada anexo con un hecho. Conserva contexto y traducciones.','Explica por qué una prueba no está razonablemente disponible; no te pongas en riesgo para conseguirla.','https://www.uscis.gov/sites/default/files/document/forms/i-589instr.pdf'),doc('Condiciones del país','Para contextualizar hechos y temor',['Informes de organismos y noticias vinculados al lugar, fecha y problema de tu caso.'],'Publicación original con autor, fecha y enlace.','Señala el pasaje pertinente; no sustituyen tus hechos personales.','Usa fuentes verificables y explica la relación con tu situación.','https://www.uscis.gov/sites/default/files/document/forms/i-589instr.pdf')],
family:[doc('Estatus del peticionario','Según ciudadanía o residencia',['Pasaporte estadounidense, acta de nacimiento estadounidense o certificado de ciudadanía/naturalización, según corresponda.','Para residente: Green Card por ambas caras.'],'Documentos del peticionario.','No confundas peticionario con beneficiario.','Consulta las alternativas oficiales.','https://www.uscis.gov/i-130'),doc('Parentesco','Según familiar solicitado',['Cónyuge: acta de matrimonio y terminación legal de matrimonios anteriores.','Padre/hijo: actas que documenten el vínculo; adopción e hijastros requieren documentos específicos.'],'Registro civil y tribunales.','Incluye todas las páginas pertinentes y traducciones.','Consulta reglas de evidencia secundaria.','https://www.uscis.gov/i-130'),doc('Matrimonio de buena fe','Si la petición es conyugal',['Contrato de vivienda conjunto, estados de cuenta conjuntos, seguros o documentos de hijos comunes.','Declaraciones de personas con conocimiento directo, si aportan información pertinente.'],'Banco, arrendador, aseguradora o registros familiares.','Usa evidencia auténtica que refleje su vida real; no es necesario tener todos los ejemplos.','Explica circunstancias reales; no crees cuentas o documentos ficticios.','https://www.uscis.gov/i-130')],
adjust:[doc('Identidad y nacimiento','Según categoría',['Documento gubernamental con foto.','Acta de nacimiento emitida por autoridad civil con los datos requeridos.'],'Pasaporte y registro civil.','Revisa traducción y requisitos por categoría.','Prueba indisponibilidad y alternativas cuando se requiera; asilados/refugiados tienen reglas propias.','https://www.uscis.gov/forms/filing-guidance/checklist-of-required-initial-evidence-for-form-i-485-for-informational-purposes-only'),doc('Entrada y base del ajuste','Según categoría y situación',['I-94, sello o prueba pertinente de admisión/parole.','Recibo/aprobación de la petición base; para asilados, prueba de concesión.'],'Avisos, documentos de entrada y expediente.','I-130 aprobada no equivale a I-485 aprobada.','Busca revisión si falta una prueba de entrada o hay dudas de jurisdicción.','https://www.uscis.gov/i-485'),doc('Patrocinio económico','Cuando tu categoría lo exige',['I-864 o versión aplicable; documentación fiscal e ingresos actuales.','I-864A si corresponde al uso de ingresos de un miembro del hogar.'],'Patrocinador, IRS y empleador.','No aplica de la misma manera a todas las categorías; el ajuste como asilado no usa el paquete familiar.','Revisa exenciones o patrocinador conjunto cuando proceda.','https://www.uscis.gov/i-864'),doc('Examen médico','Cuando se requiere I-693 completo o parcial',['I-693 preparado por médico civil autorizado y documentación según instrucciones.'],'Médico civil de USCIS.','Sigue las reglas para papel o carga electrónica; no abras un sobre sin verificar la instrucción aplicable.','Localiza un médico autorizado y revisa qué historial llevar.','https://www.uscis.gov/i-693')],
citizenship:[doc('Residencia e identidad','Según tu solicitud',['Green Card por ambas caras.','Documentos de cambio de nombre o matrimonios pertinentes.'],'Tarjeta, registro civil y tribunales.','Usa la fecha de residencia, no la fecha de impresión de una tarjeta renovada.','Revisa cómo documentar pérdida o diferencias de datos.','https://www.uscis.gov/n-400'),doc('Historial de viajes','Periodo que corresponde a tu base',['Pasaportes, registros personales, itinerarios y documentos que permitan reconstruir salidas y regresos.'],'Tus registros de viaje.','No uses fechas inventadas. Revisa por separado residencia continua y presencia física.','Reconstruye con documentos y consulta si existen ausencias prolongadas.','https://www.uscis.gov/n-400'),doc('Documentos condicionales','Solo si aplican',['Resoluciones y reportes de antecedentes; prueba de pagos ordenados.','Acuerdo fiscal si debes impuestos; documentos de manutención si corresponde.'],'Tribunal, IRS o agencia correspondiente.','No todas las personas deben presentar el mismo conjunto.','Solicita registros y orientación ante antecedentes o incumplimientos.','https://www.uscis.gov/n-400')]
};
function detailedDocuments(){const list=mapProcess==='ead'?eadDocuments():evidenceDetails[mapProcess];if(!list)return false;const t=tourData[mapProcess];app.innerHTML=("<div class=\"toolreturn\"><span>"+(t.title)+" / Documentos</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Volver al mapa</button></div>"+(contextBar(t.title+(branchTitle()?' · '+branchTitle():''),'Prepara documentos concretos',3,6))+"<p>Esta lista distingue documentos, ejemplos y condiciones. No todos los ejemplos son obligatorios. Confirma los requisitos completos de tu ruta.</p><div class=\"doc-evidence-grid\">"+(list.map((d,i)=>("<article class=\"evidence-card\"><span class=\"formtag\">"+(d.when)+"</span><h2>"+(i+1)+". "+(d.title)+"</h2><h3>Qué puedes utilizar</h3><ul>"+(d.examples.map(x=>`<li>${x}</li>`).join(''))+"</ul><dl><dt>Dónde conseguirlo</dt><dd>"+(d.where)+"</dd><dt>Qué revisar</dt><dd>"+(d.check)+"</dd><dt>Si no lo tienes</dt><dd>"+(d.missing)+"</dd></dl><label class=\"check\"><input type=\"checkbox\" "+(saved['doc-detail-'+mapProcess+'-'+i]?'checked':'')+" "+guideBind("change",(function(arg8,arg9){return function(event){saved['doc-detail-'+arg8+'-'+arg9+'']=this.checked;persist()}})(mapProcess,i))+">Lo revisé para mi caso</label><details><summary>Fuente e instrucciones</summary><a href=\""+(d.source)+"\" target=\"_blank\" rel=\"noopener\">Consultar fuente oficial</a></details></article>")).join(''))+"</div>");return true}
const eduPreviousMapStage=mapStage;mapStage=function(i){if(i===2&&detailedDocuments())return;if(mapProcess==='ead'){if(i===0){eadRouteHelp();return}if(i===3){startEadLesson();return}if(i===4){eadPacket();return}if(i===5){eadFinalReview();return}}eduPreviousMapStage(i)};
function eadRouteHelp(){app.innerHTML=("<div class=\"toolreturn\"><span>Permiso de trabajo / Ruta</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Mi mapa</button></div>"+(contextBar('Permiso de trabajo · '+eadLabel(),'Confirma qué ruta estás preparando',1,6))+"<article class=\"card\"><h2>Tu selección organiza la guía; no determina elegibilidad</h2><p>"+(eadProfile.base==='c8'?'Para un primer EAD por asilo pendiente, el aviso de USCIS explica una espera de 150 días para solicitar y 180 días para poder recibirlo. Los retrasos atribuibles al solicitante no cuentan. No calcules tu reloj solo sumando días de calendario.':eadProfile.base==='c9'?'La ruta (c)(9) corresponde a determinados ajustes pendientes bajo INA 245. Si tu ajuste se basa en asilo ya concedido, revisa la categoría de asilado en lugar de asumir (c)(9).':'Necesitas identificar tu categoría antes de seguir una lista o elegir una opción del formulario.')+"</p><h3>El método también cambia el recorrido</h3><p>El formulario guiado, la carga de PDF y el envío en papel tienen reglas y categorías habilitadas diferentes. La captura de una opción no demuestra que esté disponible para tu caso.</p><div class=\"actions\">"+(ext(eduSources.online,'Verificar método y categoría'))+(ext(eadProfile.base==='c8'?eduSources.clock:eduSources.ead,'Revisar requisitos de mi ruta'))+"</div></article>")}
const eadLessons=[
[3,[330,122,478,502],'Abre el formulario correcto','En tu cuenta, busca “File a form online” y elige I-765. Confirma que la categoría y el método estén habilitados antes de empezar.','Ten a mano la base migratoria de tu solicitud. I-765 es el permiso de trabajo; no presenta por sí solo una solicitud de asilo.','No selecciones otra categoría para conseguir que el sistema te deje continuar.',eduSources.online],
[8,[319,122,603,317],'Identifica la categoría','En “Basis of eligibility”, localiza la categoría que corresponde a tu situación. Esta ruta explica asilo pendiente (c)(8).','Compara tu recibo de I-589 y tu historial; asilo aprobado y ajuste pendiente tienen bases diferentes.','Una opción visible en esta captura histórica no confirma disponibilidad actual.',eduSources.ead],
[13,[319,122,402,404],'Explica por qué solicitas','Distingue solicitud inicial, renovación y reemplazo. Responde también si has presentado una I-765 anteriormente.','Inicial no significa simplemente primera solicitud por internet. Revisa permisos y solicitudes anteriores.','No copies la opción marcada en la imagen: es un ejemplo público.',eduSources.ead],
[20,[319,122,458,500],'Escribe tus nombres','Copia tu nombre legal en los campos correspondientes. Revisa también otros nombres utilizados y las instrucciones para nombres únicos.','Compara pasaporte, acta y recibos. Si hay diferencias, identifica su causa y el documento que las explica.','No intercambies apellidos con nombres ni omitas otros nombres solo porque no aparecen en un recibo.',eduSources.ead],
[21,[319,122,618,516],'Separa dirección postal y residencia','La dirección postal es donde recibirás correspondencia. Si vives en otro lugar, responde esa diferencia y completa la dirección física.','Comprueba número de apartamento, ciudad, estado y ZIP. “In care of” identifica a quien recibe tu correo cuando corresponda.','Presentar una I-765 no sustituye todos los cambios de dirección que debas reportar.',eduSources.tips],
[25,[319,122,619,480],'Consulta tus registros migratorios','Ubica cada dato en su documento: I-94, pasaporte, última entrada y estatus actual son conceptos diferentes. Sigue la pregunta exacta del formulario.','El número de pasaporte no es el número de I-94. Una fecha de vencimiento del pasaporte tampoco es la fecha autorizada de estancia.','No deduzcas tu estatus actual solamente a partir de una entrada antigua. Busca ayuda si tus registros difieren.',eduSources.i94],
[28,[319,122,583,481],'Carga la fotografía solicitada','Prepara un archivo de fotografía tipo pasaporte que cumpla las especificaciones indicadas en tu cuenta.','Revisa rostro completo, fondo claro, nitidez y dimensiones. Una fotografía de la página del pasaporte no reemplaza esta foto.','No uses filtros ni imágenes que modifiquen tu apariencia.',eduSources.photo],
[29,[319,122,464,500],'Adjunta el registro de entrada cuando corresponda','Lee el título de evidencia y las alternativas que admite. Usa una copia completa y legible del documento requerido.','I-94 en papel: revisa ambas caras. Para uno electrónico, conserva el registro descargado del portal oficial.','Las exigencias dependen de la categoría; no conviertas esta pantalla en un requisito universal.',eduSources.check],
[30,[319,122,575,470],'Adjunta tu permiso anterior o identidad','Si ya recibiste un EAD, prepara anverso y reverso. Si nunca tuviste uno, revisa la identificación gubernamental alternativa admitida.','Amplía cada archivo antes de cargarlo: nombre, fotografía y números deben ser legibles y los bordes completos.','No envíes únicamente el frente de un documento cuando se requieren ambas caras.',eduSources.check],
[40,[319,122,378,501],'Documenta el asilo pendiente','Identifica el recibo de USCIS de la I-589 o el documento de presentación ante corte que corresponda a tu ruta. Lee las instrucciones completas de evidencia.','Un aviso de comparecencia ante corte (NTA), por sí solo, no demuestra que presentaste la I-589. Revisa fecha y datos del documento.','No confundas prueba de presentación con la verificación del reloj de asilo.',eduSources.clock],
[50,[319,122,602,482],'Compara el resumen con tus documentos','Antes de certificar, revisa cada respuesta y cada anexo. Utiliza la opción de descargar o imprimir el resumen si está disponible.','Comprueba categoría, motivo, nombres, direcciones, fechas, traducciones y archivos completos. Corrige en la sección original.','La IA o una lista completada no garantizan elegibilidad, exactitud ni aprobación.',eduSources.tips]
];
function startEadLesson(){eduScreen=0;if(eadProfile.base==='c8'&&eadProfile.method==='online')renderEadLesson();else eadMethodLesson()}
function renderEadLesson(){const s=eadLessons[eduScreen];app.innerHTML=("<div class=\"toolreturn\"><span>I-765 / "+(eadLabel())+"</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Mi mapa</button></div>"+(contextBar('Permiso de trabajo · '+eadLabel(),'Aprende en pantalla',eduScreen+1,eadLessons.length))+"<p class=\"reference-note\">Pantallas públicas de referencia de USCIS · colección 2025, alojada en un espejo independiente. La interfaz puede cambiar. No contienen datos tuyos ni muestran una sesión actual.</p><div class=\"learning-layout\"><figure class=\"screen-frame\"><svg viewBox=\""+(s[1].join(' '))+"\" role=\"img\" aria-label=\"Pantalla de referencia: "+(s[2])+"\"><image href=\"assets/ead-online"+(s[0])+".jpg\" width=\"1363\" height=\"936\"/></svg><figcaption>"+(s[2])+" · <a href=\"assets/ead-online"+(s[0])+".jpg\" target=\"_blank\">Ampliar captura completa</a></figcaption></figure><article class=\"lesson-card\"><span class=\"formtag\">I-765 · Paso "+(eduScreen+1)+" de "+(eadLessons.length)+"</span><h2>"+(s[2])+"</h2><h3>Haz esto en tu cuenta</h3><p>"+(s[3])+"</p><h3>Comprueba antes de continuar</h3><p>"+(s[4])+"</p><aside class=\"lesson-tip\"><b>Evita este error</b><p>"+(s[5])+"</p></aside>"+(ext(s[6],'Consultar instrucción oficial'))+"<details><summary>Origen de la imagen</summary><p>Documento público USCIS I-765 Mock Deck, 2025. Captura de su pantalla de referencia; no es una reproducción de una cuenta real.</p>"+(ext(eduSources.screens,'Abrir documento público de pantallas'))+"</details></article></div><div class=\"lesson-footer\"><button "+guideBind("click",(function(){return function(event){eduScreen=Math.max(0,eduScreen-1);renderEadLesson()}})())+" "+(eduScreen===0?'disabled':'')+">← Anterior</button><span>"+(eduScreen+1)+" / "+(eadLessons.length)+"</span><button class=\"primary\" "+guideBind("click",guideActionByText(eduScreen<eadLessons.length-1?'eduScreen++;renderEadLesson()':'eadFinalReview()'))+">"+(eduScreen<eadLessons.length-1?'Siguiente paso →':'Revisión antes de enviar →')+"</button></div>");app.scrollIntoView({block:"start",behavior:"instant"})}
function eadMethodLesson(){app.innerHTML=("<div class=\"toolreturn\"><span>Permiso de trabajo</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Mi mapa</button></div>"+(contextBar('I-765 · '+eadLabel(),'Escoge el recorrido de presentación correcto',4,6))+"<article class=\"card\"><h2>"+(eadProfile.method==='paper'?'Preparar el formulario en papel':eadProfile.method==='pdf'?'Presentación mediante PDF':'Verifica si tu categoría admite el formulario guiado')+"</h2><p>El recorrido guiado de (c)(8) no representa el recorrido de (c)(9). USCIS mantiene listas distintas para formularios guiados y presentación mediante PDF. Comprueba tu categoría en la lista actual antes de elegir el método.</p><ol><li>Abre la página oficial I-765 y descarga el formulario y sus instrucciones actuales. Comprueba la edición aceptada.</li><li>Completa las preguntas según tus registros; compara nombre, entrada, categoría y motivo con sus documentos.</li><li>Prepara la evidencia específica de tu categoría. Para (c)(9) presentada separadamente, revisa la prueba de I-485 pendiente; un recibo I-130 no la sustituye.</li><li>En papel, confirma dirección de envío según categoría y lugar de residencia. En PDF, sigue las instrucciones específicas de carga, firma y anexos.</li><li>Comprueba tarifa y posibles exenciones vigentes antes de pagar. No asumas que presentar por internet conserva una exención.</li></ol><div class=\"actions\">"+(ext(eduSources.ead,'Formulario e instrucciones vigentes'))+(ext(eduSources.online,'Categorías y métodos en línea'))+(ext(eduSources.address,'Direcciones de presentación'))+"</div><p class=\"reference-note\">Las imágenes del formulario que puedes explorar a continuación son referencia de una edición anterior, no una copia para presentar.</p><button class=\"primary\" "+guideBind("click",(function(){return function(event){startVisual('ead')}})())+">Explorar campos en el formulario de referencia →</button><button "+guideBind("click",(function(){return function(event){detailedDocuments()}})())+">Ver mis documentos concretos</button></article>")}
function eadFinalReview(){app.innerHTML=("<div class=\"toolreturn\"><span>I-765 / Revisión</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Mi mapa</button></div>"+(contextBar('Permiso de trabajo · '+eadLabel(),'Antes de certificar y enviar',6,6))+"<article class=\"card\"><h2>Revisa en tu cuenta, con tus documentos</h2><p>La guía no envía tu solicitud. Consulta a un abogado o representante acreditado si tienes dudas sobre elegibilidad, antecedentes, inconsistencias o categoría.</p>"+(['La categoría y el método corresponden a mi situación y están habilitados actualmente.','Comparé las respuestas con mis registros; no copié respuestas del ejemplo.','Abrí cada archivo: está completo, legible y con traducción certificada cuando corresponde.','Revisé la certificación, firma e información del preparador o intérprete si alguien me ayudó.','Verifiqué la tarifa vigente y las instrucciones de pago o exención para mi categoría.','Después de presentar guardaré copia, confirmación y recibo; revisaré avisos y solicitudes de evidencia.'].map(x=>`<label class="check"><input type="checkbox">${x}</label>`).join(''))+"<div class=\"actions\">"+(ext(eduSources.fees,'Comprobar tarifa oficial'))+(ext(eduSources.tips,'Instrucciones de presentación en línea'))+"</div><button "+guideBind("click",(function(){return function(event){eadPacket()}})())+">Preparar carta e índice →</button></article>")}
function eadPacket(){const docs=eadDocuments();app.innerHTML=("<div class=\"toolreturn\"><span>I-765 / Carta e índice</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">← Mi mapa</button></div>"+(contextBar('Permiso de trabajo · '+eadLabel(),'Organiza tus anexos',5,6))+"<article class=\"card\"><h2>Un índice que corresponde a tu ruta</h2><p>Edita los espacios y elimina lo que no aplique. El índice ayuda a organizar, pero no reemplaza formularios ni evidencia. En línea, carga cada archivo en el apartado solicitado; no adjuntes un paquete único por costumbre.</p><textarea id=\"eadPacketText\" rows=\"22\" style=\"width:100%;padding:20px;border-radius:16px;border:1px solid #b4ccec\">"+(['[Fecha]','USCIS','[Dirección oficial vigente: solo si presentarás en papel]','','RE: Form I-765 — [nombre del solicitante]','Categoría seleccionada: '+eadLabel(),'','A quien corresponda:','Adjunto mi Formulario I-765 y los documentos que se enumeran a continuación. [Describe únicamente documentos que realmente incluyes.]','','ÍNDICE PROPUESTO','1. Formulario I-765 completo y firmado, según método.',...docs.map((d,i)=>`${i+2}. ${d.title} — [especifica documento, fecha y páginas; elimina si no aplica].`),'','[Agrega pago o documentación de exención solo conforme a las instrucciones vigentes.]','[Nombre y firma, cuando corresponda]'].join('\n'))+"</textarea><button class=\"primary\" "+guideBind("click",(function(){return function(event){downloadEadPacket()}})())+">Descargar carta e índice editados</button></article>")}
function downloadEadPacket(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([document.querySelector('#eadPacketText').value],{type:'text/plain;charset=utf-8'}));a.download='I-765-carta-indice.txt';a.click();URL.revokeObjectURL(a.href)}

/* Start with one choice, then open the image instead of requiring map navigation. */
const friendlyFilter=processFilterChanged;
processPicker=function(){mapProcess='';mapCategory='';document.body.classList.remove('in-lesson');document.querySelector('.hero h1').innerHTML='Vamos a hacerlo<br><span>paso a paso.</span>';document.querySelector('.hero > p').textContent='Elige tu trámite. Te mostraremos la primera pantalla y qué hacer en ella.';app.innerHTML=("<section class=\"start-layout\"><div class=\"start-choice\"><span class=\"formtag\">EMPIEZA AQUÍ · 1 DE 2</span><h2>¿Qué quieres preparar?</h2><p>No necesitas saber el número del formulario.</p><label for=\"processChoice\">Selecciona tu trámite</label><select id=\"processChoice\" "+guideBind("change",(function(){return function(event){processFilterChanged(this.value)}})())+"><option value=\"\">Toca aquí para elegir…</option>"+(Object.entries(tourData).map(([k,t])=>`<option value="${k}">${t.icon} ${t.title}</option>`).join(''))+"</select><div id=\"subfilter\"></div><button id=\"openMap\" class=\"primary start-button\" disabled "+guideBind("click",(function(){return function(event){chooseProcess()}})())+">Empezar mi guía con imágenes →</button><p class=\"muted\">Puedes consultar el mapa y los documentos dentro de tu guía.</p></div><div class=\"start-preview\" id=\"startPreview\"><span class=\"formtag\">ASÍ TE VAMOS A GUIAR</span><h2>Mira la pantalla.<br>Lee la indicación.<br>Da el siguiente paso.</h2><img src=\"assets/myuscis-home.jpg\" alt=\"Ejemplo real de la página pública myUSCIS que se explica en la guía\"><p>Ejemplo: página pública de myUSCIS. Al elegir tu trámite, verás la imagen correspondiente cuando esté disponible.</p><ol><li>Elige lo que necesitas hacer.</li><li>Responde unas preguntas para ubicar tu ruta.</li><li>Avanza con una imagen y una acción a la vez.</li></ol></div></section>")};
processFilterChanged=function(k){friendlyFilter(k);const preview=document.querySelector('#startPreview');if(!k)return;const t=tourData[k];let image='',caption='';if(k==='ead'){image='ead-online3.jpg';caption='Pantalla pública de referencia USCIS (2025). Te explicamos qué opción buscar.'}else if(visualGuides[k]){image=visualGuides[k].slides[0].image;caption='Referencia del formulario: se explica cada zona. Comprueba la edición vigente antes de presentar.'}else if(k==='account'){image='myuscis-register.jpg';caption='Página pública real de creación de cuenta myUSCIS.'}else if(k==='foia'){image='first-home.jpg';caption='Página pública real de FIRST, el sistema de registros de USCIS.'}preview.innerHTML=`<span class="formtag">TU GUÍA · ${t.form}</span><h2>${t.icon} ${t.title}</h2>${image?`<img src="assets/${image}" alt="Vista previa de ${t.title}"><p>${caption}</p>`:'<p>Este proceso tiene orientación inicial. Su secuencia de capturas específicas todavía está pendiente; te lo indicaremos antes de empezar.</p>'}<p><b>Tu siguiente acción:</b> ${k==='ead'?'responde las tres preguntas de la izquierda y pulsa “Empezar mi guía”.':'revisa las opciones de tu trámite y pulsa “Empezar mi guía”.'}</p>`;document.querySelector('#openMap').textContent=image?'Empezar mi guía con imágenes →':'Empezar orientación inicial →'};
chooseProcess=function(){mapProcess=document.querySelector('#processChoice').value;mapCategory=document.querySelector('#categoryChoice')?.value||'';if(mapProcess==='ead'){eadProfile={base:document.querySelector('#eadBase').value,kind:document.querySelector('#eadKind').value,method:document.querySelector('#eadMethod').value};if(!eadProfile.base||!eadProfile.kind)return;startEadLesson()}else if(visualGuides[mapProcess])startVisual(mapProcess);else if(mapProcess==='account'||mapProcess==='foia'){friendlyPortalStep=0;renderFriendlyPortal()}else{mapStage(0)}document.body.classList.add('in-lesson');app.scrollIntoView({block:'start'})};
let friendlyPortalStep=0;
const friendlyPortal={account:[['myuscis-home.jpg','Abre myUSCIS','Entra en myUSCIS desde el enlace oficial. Si ya tienes cuenta, usa la opción de iniciar sesión. Si no tienes, continúa al siguiente paso.','La cuenta personal es para el solicitante. No compartas tu contraseña ni códigos de acceso.',realScreens[0].source],['myuscis-register.jpg','Crea tu cuenta personal','En la página de registro, escribe tu correo y su confirmación. Sigue la verificación que USCIS envíe a ese correo.','Comprueba que puedes acceder al correo. La imagen muestra el inicio público del registro, no todas las pantallas de verificación.',realScreens[0].source]],foia:[['first-home.jpg','Solicita tus registros en FIRST','Abre el sistema oficial y busca la opción para solicitar registros. Antes de continuar, distingue si pides tus propios registros o los de otra persona.','Esta pantalla pertenece a USCIS. Los registros de corte y otras agencias tienen procedimientos diferentes.',links.foia],['first-status.jpg','Aprende a consultar el seguimiento','Esta pantalla permite consultar una solicitud FOIA ya presentada. Usa el identificador de tu solicitud cuando lo tengas.','La imagen es una referencia de seguimiento; no significa que esta guía haya creado una solicitud.',links.foia]]};
function renderFriendlyPortal(){const s=friendlyPortal[mapProcess][friendlyPortalStep],t=tourData[mapProcess];app.innerHTML=("<div class=\"toolreturn\"><span>"+(t.title)+"</span><button "+guideBind("click",(function(){return function(event){processPicker()}})())+">Cambiar trámite</button><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Ver mi mapa</button></div>"+(contextBar(t.title,'Mira la imagen y sigue la indicación',friendlyPortalStep+1,friendlyPortal[mapProcess].length))+"<div class=\"learning-layout\"><figure class=\"screen-frame\"><img style=\"width:100%\" src=\"assets/"+(s[0])+"\" alt=\"Pantalla pública real: "+(s[1])+"\"><figcaption>Captura pública de referencia · No es tu cuenta.</figcaption></figure><article class=\"lesson-card\"><span class=\"formtag\">AHORA HAZ ESTO</span><h2>"+(s[1])+"</h2><p>"+(s[2])+"</p><aside class=\"lesson-tip\">"+(s[3])+"</aside><div class=\"actions\">"+(ext(s[4],'Abrir portal oficial'))+"</div><p>Realiza la acción en el portal oficial y regresa aquí para continuar.</p><button class=\"primary\" "+guideBind("click",guideActionByText(friendlyPortalStep===0?'friendlyPortalStep++;renderFriendlyPortal()':'mapStage(2)'))+">"+(friendlyPortalStep===0?'Entendido · Siguiente imagen →':'Ver qué documentos preparar →')+"</button></article></div>");app.scrollIntoView({block:'start'})}
/* Native images render independently of SVG external-image support. */
function nativeScreen(image,crop,alt){const[x,y,w,h]=crop;return `<div class="native-crop" style="aspect-ratio:${w}/${h}"><img src="assets/${image}" alt="${alt}" style="width:${1363/w*100}%;left:${-x/w*100}%;top:${-y/h*100}%" onerror="this.closest('.native-crop').insertAdjacentHTML('afterend','<p class=&quot;image-error&quot;>La imagen no pudo cargarse. Recarga la página para intentarlo de nuevo.</p>')"></div>`}
const friendlyEadRender=renderEadLesson;
renderEadLesson=function(){friendlyEadRender();document.body.classList.add('in-lesson');const s=eadLessons[eduScreen];document.querySelector('.screen-frame svg').outerHTML=nativeScreen('ead-online'+s[0]+'.jpg',s[1],s[2]);const tip=document.querySelector('.lesson-card');if(eduScreen===0)tip.insertAdjacentHTML('afterbegin',`<div class="actions">${ext(realScreens[0].source,'Abrir myUSCIS')}</div><p><b>Primero:</b> inicia sesión en tu cuenta. Luego busca “File a form online” y selecciona I-765, como muestra la imagen.</p><details><summary>No tengo cuenta, ¿cómo empiezo?</summary><p>Abre myUSCIS y busca la opción para crear una cuenta personal. Necesitarás un correo al que tengas acceso. Sigue los mensajes de verificación de USCIS.</p><img src="assets/myuscis-register.jpg" alt="Página pública de registro de myUSCIS" style="width:100%">${ext(realScreens[0].source,'Ir a myUSCIS')}</details>`);tip.insertAdjacentHTML('afterbegin','<p class="doing-now">① Observa la imagen &nbsp; ② Hazlo en el portal oficial &nbsp; ③ Pulsa Siguiente</p>');app.scrollIntoView({block:'start'})};
const friendlyVisualRender=renderVisual;
renderVisual=function(){friendlyVisualRender();document.body.classList.add('in-lesson');const g=visualGuides[visualKey],s=g.slides[visualPage],p=s.spots[visualSpot],c=s.crop;let v=c;if(visualFocus)v=[Math.max(c[0],p[0]-30),Math.max(c[1],p[1]-30),Math.min(c[2],p[2]+60),Math.min(c[3],p[3]+60)];document.querySelector('.contextbar').outerHTML=contextBar(g.name+(branchTitle()?' · '+branchTitle():''),'Reconoce los campos en la imagen',visualPage+1,g.slides.length);const figure=document.querySelector('.real-document');figure.querySelector('svg').outerHTML=nativeScreen(s.image,v,g.form+': '+s.title);const box=figure.querySelector('.native-crop');box.insertAdjacentHTML('beforeend',`<span class="field-outline" style="left:${(p[0]-v[0])/v[2]*100}%;top:${(p[1]-v[1])/v[3]*100}%;width:${p[2]/v[2]*100}%;height:${p[3]/v[3]*100}%"></span>${s.spots.map((q,j)=>("<button class=\"native-spot\" style=\"left:"+((q[0]+15-v[0])/v[2]*100)+"%;top:"+((q[1]+15-v[1])/v[3]*100)+"%\" aria-label=\"Explicar "+(q[4])+"\" "+guideBind("click",(function(arg3){return function(event){selectVisualSpot(arg3)}})(j))+">"+(j+1)+"</button>")).join('')}`);document.querySelector('.visual-explanation').insertAdjacentHTML('afterbegin',`<span class="formtag">OBSERVA LA ZONA MARCADA</span><p>Lee la explicación y busca esa zona en tu formulario. La imagen es una referencia de edición ${g.edition}; descarga la versión vigente antes de completarla.</p>${ext(g.official,'Abrir formulario oficial')}`);app.scrollIntoView({block:'start'})};
const friendlyMap=mapView;mapView=function(){friendlyMap();document.body.classList.add('in-lesson');app.insertAdjacentHTML('afterbegin',("<div class=\"next-action\"><b>¿No sabes dónde empezar?</b><p>Abre la guía visual: verás una imagen con su explicación desde el primer paso.</p><button class=\"primary\" "+guideBind("click",guideActionByText(mapProcess==='ead'?'startEadLesson()':visualGuides[mapProcess]?`startVisual('${mapProcess}')`:friendlyPortal[mapProcess]?'friendlyPortalStep=0;renderFriendlyPortal()':'mapStage(0)'))+">Comenzar paso a paso →</button></div>"));app.scrollIntoView({block:'start'})};
processPicker();
window.scrollTo(0,0);
/* Explain every image and state the prerequisite at the moment it is needed. */
function captureReady(key,text){return ("<label class=\"capture-ready\"><input type=\"checkbox\" "+(saved['ready-'+key]?'checked':'')+" "+guideBind("change",(function(arg1){return function(event){saved['ready-'+arg1+'']=this.checked;persist()}})(key))+">"+(text)+"</label>")}
const captureVisualRender=renderVisual;
renderVisual=function(){captureVisualRender();const g=visualGuides[visualKey],s=g.slides[visualPage],p=s.spots[visualSpot];document.querySelector('.visual-explanation').innerHTML=("<div class=\"capture-required\"><span class=\"formtag\">ANTES DE ESTE PASO</span><h3>Ten abierto tu formulario "+(g.form)+"</h3><p>Descarga la edición vigente desde USCIS y ábrela en tu dispositivo. Busca la sección “"+(s.title)+"”. La numeración puede cambiar entre ediciones.</p>"+(ext(g.official,'Descargar formulario vigente'))+(captureReady('form-'+visualKey,'Ya tengo abierto el formulario vigente'))+"</div><div class=\"capture-explanation\"><span class=\"formtag\">¿QUÉ MUESTRA ESTA IMAGEN?</span><h2>"+(s.title)+"</h2><p>Es una imagen del formulario "+(g.form)+", página "+(s.page)+" de la copia de referencia. La zona resaltada corresponde a <b>"+(p[4])+"</b>.</p><span class=\"formtag\">¿QUÉ HAGO AQUÍ?</span><p aria-live=\"polite\">"+(p[5])+"</p><p class=\"capture-tip\">Busca esa misma pregunta en tu formulario y utiliza tus propios documentos. Los puntos numerados explican otras zonas de esta imagen.</p></div><button class=\"primary\" "+guideBind("click",(function(){return function(event){nextVisualSpot()}})())+">"+(visualSpot<s.spots.length-1?'Entendido · Siguiente zona →':visualPage<g.slides.length-1?'Ir a la siguiente pantalla →':'Terminar recorrido visual ✓')+"</button><button "+guideBind("click",(function(){return function(event){visualFocus=!visualFocus;renderVisual()}})())+">"+(visualFocus?'Ver página completa':'Ampliar zona resaltada')+"</button><details><summary>Imagen de referencia y fuentes</summary><p>Esta captura es de la edición "+(g.edition)+(g.draft?', un borrador público que no debe presentarse':'')+". Sirve para reconocer campos; verifica la versión y las instrucciones vigentes. Explicamos zonas seleccionadas, no todos los campos.</p>"+(ext(g.source,'Ver documento de referencia'))+(ext(g.official,'Ver instrucciones oficiales'))+"</details>");document.querySelector('.real-document figcaption').innerHTML=`<b>Estás viendo:</b> ${g.form} · ${s.title} · Zona: ${p[4]}.<br>Referencia ${g.edition}${g.draft?' · BORRADOR, NO PRESENTAR':''}. Las marcas son de IMMIGRA.`};
const captureEadNeeds=[
['I-765 abierta en tu cuenta','Inicia sesión en myUSCIS. Desde “File a form online”, abre I-765 para ver las opciones de tu categoría.'],
['I-765 abierta y prueba de tu categoría','Ten a mano el recibo o la constancia de tu I-589 y consulta los requisitos de (c)(8).'],
['I-765 abierta y tu historial de solicitudes','Revisa si ya presentaste una I-765 y si recibiste un EAD. Esto ayuda a distinguir inicial, renovación y reemplazo.'],
['I-765 abierta y documentos de identidad','Ten a mano tu pasaporte, documentos de identidad y documentos de cambios de nombre, si corresponden.'],
['I-765 abierta y tus direcciones completas','Ten anotadas tu dirección postal y tu residencia actual, incluidos apartamento y ZIP.'],
['I-765 abierta y registros de entrada','Ten a mano tu pasaporte, I-94 si existe y documentos que expliquen tu situación actual.'],
['I-765 abierta y el archivo de tu fotografía','Prepara la fotografía con las especificaciones que pide tu cuenta antes de llegar a la carga.'],
['I-765 abierta y el archivo de entrada requerido','Ten lista una copia legible del I-94 o la alternativa que admitan las instrucciones de tu categoría.'],
['I-765 abierta y tus copias de identidad','Prepara las dos caras del EAD anterior si lo tienes, o la identificación alternativa admitida.'],
['I-765 abierta y prueba de presentación de asilo','Localiza el recibo I-589 o la constancia de presentación ante corte que corresponda.'],
['I-765 completada y tus anexos','Ten los documentos originales a la vista para comparar el resumen y abre cada archivo que cargaste.']
];
const captureEadRender=renderEadLesson;
renderEadLesson=function(){captureEadRender();const s=eadLessons[eduScreen],n=captureEadNeeds[eduScreen];document.querySelector('.lesson-card').insertAdjacentHTML('afterbegin',`<div class="capture-required"><span class="formtag">ANTES DE ESTE PASO</span><h3>${n[0]}</h3><p>${n[1]}</p>${eduScreen===0?ext(realScreens[0].source,'Abrir myUSCIS'):''}${captureReady('ead-screen-'+eduScreen,'Ya tengo listo lo necesario para este paso')}</div><div class="capture-explanation"><span class="formtag">¿QUÉ MUESTRA ESTA IMAGEN?</span><p><b>${s[2]}.</b> Es la pantalla de referencia del recorrido I-765 que se explica abajo. Busca el mismo apartado en tu solicitud abierta; el diseño puede variar.</p></div>`);document.querySelector('.screen-frame figcaption').insertAdjacentHTML('afterbegin','<b>Estás viendo:</b> ')};
const capturePortalRender=renderFriendlyPortal;
renderFriendlyPortal=function(){capturePortalRender();const s=friendlyPortal[mapProcess][friendlyPortalStep];let title='',need='';if(mapProcess==='account'){title='Ten acceso a tu correo electrónico';need='Este paso es para acceder o crear una cuenta. El formulario migratorio se abre después de entrar al portal.'}else if(friendlyPortalStep===0){title='Identifica qué registros quieres solicitar';need='Ten clara la agencia que tiene los registros y si solicitas los tuyos o los de otra persona. La solicitud FOIA se prepara dentro del sistema FIRST.'}else{title='Ten el identificador de tu solicitud FOIA';need='Este paso corresponde al seguimiento de una solicitud ya presentada. No es la pantalla para comenzar una nueva.'}document.querySelector('.lesson-card').insertAdjacentHTML('afterbegin',`<div class="capture-required"><span class="formtag">ANTES DE ESTE PASO</span><h3>${title}</h3><p>${need}</p>${captureReady('portal-'+mapProcess+'-'+friendlyPortalStep,'Ya tengo lo necesario para seguir')}</div><div class="capture-explanation"><span class="formtag">¿QUÉ MUESTRA ESTA IMAGEN?</span><p>La página pública de referencia: <b>${s[1]}</b>. Reconoce las opciones de acceso; esta imagen no muestra tu cuenta ni tus datos.</p></div>`)};

/* Completion questions belong to both the I-130 and family-adjustment routes. */
let familyPrep=saved.familyPrep||{relationship:'',route:'',i130:'',i130a:'',support:'',ead:'',i485:''};
const familyStatusOptions=[['','Selecciona…'],['no','No lo he empezado'],['draft','Lo estoy completando'],['complete','Lo completé, pero no lo he presentado'],['filed','Ya lo presenté'],['unknown','No estoy seguro']];
function familySelect(id,label,options=familyStatusOptions){return ("<label for=\"fp-"+(id)+"\">"+(label)+"</label><select id=\"fp-"+(id)+"\" "+guideBind("change",(function(arg3){return function(event){familyPrep[''+arg3+'']=this.value;saved.familyPrep=familyPrep;persist();familyQuestions()}})(id))+">"+(options.map(([v,t])=>`<option value="${v}" ${familyPrep[id]===v?'selected':''}>${t}</option>`).join(''))+"</select>")}
familyQuestions=function(){const spouse=familyPrep.relationship==='spouse',aos=familyPrep.route==='adjust',consular=familyPrep.route==='consular';document.body.classList.add('in-lesson');app.innerHTML=("<div class=\"toolreturn\"><span>Ruta familiar / Preparación de formularios</span><button "+guideBind("click",(function(){return function(event){processPicker()}})())+">Cambiar trámite</button><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Ver mi mapa</button></div>"+(contextBar('Petición familiar','Primero: ¿qué tienes preparado?',1,2))+"<article class=\"family-question-card\"><h2>Revisemos tus formularios, uno por uno</h2><p>Completar un formulario y presentarlo son pasos diferentes. Tus respuestas organizan la guía; no confirman que puedas presentar o ajustar estatus.</p><div class=\"family-question-grid\"><section>"+(familySelect('relationship','¿Qué relación tiene el beneficiario con el peticionario?',[['','Selecciona…'],['spouse','Es su cónyuge'],['child','Es su hijo o hija / hijastro'],['parent','Es su padre o madre'],['other','Otra relación / por confirmar']]))+(familySelect('route','¿Qué parte del proceso estás preparando?',[['','Selecciona…'],['petition','Solo la petición familiar I-130 por ahora'],['adjust','Petición y/o ajuste dentro de EE. UU.'],['consular','Proceso de visa de inmigrante en consulado'],['unknown','No sé cuál es mi ruta']]))+"</section><section class=\"family-question-help\"><h3>¿Por qué lo preguntamos?</h3><p>La I-130 acredita el vínculo familiar. La I-130A corresponde a peticiones para cónyuge. El patrocinio económico se revisa en la etapa de residencia o visa, y el permiso de trabajo requiere una base propia.</p></section></div><section class=\"family-form-question\"><span class=\"formtag\">1 · PETICIÓN FAMILIAR</span>"+(familySelect('i130','¿Ya completaste la I-130?',[...familyStatusOptions,['approved','La petición ya fue aprobada']]))+"</section>"+(spouse?`<section class="family-form-question"><span class="formtag">2 · SUPLEMENTO CONYUGAL</span>${familySelect('i130a','¿Ya completaste la I-130A del cónyuge beneficiario?')}<p>Revisa este suplemento junto con la petición conyugal. Si la I-130 ya se presentó, comprueba qué se incluyó antes de enviar documentos adicionales.</p></section>`:familyPrep.relationship?'<p class="family-stage-note">I-130A: se muestra para peticiones de cónyuge; no se añade automáticamente a los demás parentescos.</p>':'')+(aos||consular?`<section class="family-form-question"><span class="formtag">${spouse?'3':'2'} · PATROCINIO ECONÓMICO</span>${familySelect('support','¿Ya preparaste el patrocinio económico (I-864 o versión aplicable)?',[...familyStatusOptions,['exempt','Creo que existe una exención: necesito confirmarla']])}<p>Revisa requisitos, exenciones y anexos de ingresos. El patrocinador conjunto y el miembro del hogar tienen funciones diferentes; I-864A no sustituye automáticamente una I-864.</p></section>`:familyPrep.route?'<p class="family-stage-note"><b>Patrocinio económico:</b> si preparas únicamente la I-130, se revisará en la etapa de ajuste o visa de inmigrante. No lo agregues automáticamente al envío inicial de la petición.</p>':'')+(aos?`<section class="family-form-question"><span class="formtag">AJUSTE DE ESTATUS</span>${familySelect('i485','¿En qué estado está la I-485?',[['','Selecciona…'],['prepare','Aún no la presenté / la estoy preparando'],['pending','Ya la presenté y está pendiente'],['unknown','No sé si puedo presentar una I-485']])}</section><section class="family-form-question"><span class="formtag">PERMISO DE TRABAJO · BENEFICIO OPCIONAL</span>${familySelect('ead','¿Quieres solicitar permiso de trabajo y ya completaste la I-765?',[['','Selecciona…'],['no','Sí lo quiero; no he empezado la I-765'],['draft','Sí; la estoy completando'],['complete','La completé, pero no la presenté'],['filed','Ya presenté la I-765'],['skip','No deseo solicitarlo ahora'],['unknown','No sé si me corresponde']])}<p>La I-130 por sí sola no concede permiso de trabajo. Para la ruta de ajuste, revisa la base de la I-765 y la I-485, junto con sus instrucciones y tarifas.</p></section>`:familyPrep.route?'<p class="family-stage-note"><b>Permiso de trabajo:</b> no se incluye automáticamente con una petición I-130 o con el trámite consular. Si necesitas trabajar en EE. UU., hay que revisar una base de autorización independiente.</p>':'')+"<button class=\"primary start-button\" "+guideBind("click",(function(){return function(event){familyPrepResult()}})())+">Ver qué tengo listo y qué falta →</button><p id=\"familyValidation\" role=\"alert\"></p></article>")};
function familyPrepResult(){const p=familyPrep;if(!p.relationship||!p.route||!p.i130||(p.relationship==='spouse'&&!p.i130a)||(['adjust','consular'].includes(p.route)&&!p.support)||(p.route==='adjust'&&(!p.ead||!p.i485))){document.querySelector('#familyValidation').textContent='Responde las preguntas visibles. Puedes elegir “No estoy seguro” si aún no lo sabes.';return}saved.familyPrep=p;persist();const labels={no:'Por comenzar',draft:'En preparación',complete:'Completado, sin presentar',filed:'Presentado según tu respuesta',approved:'Aprobada según tu respuesta',unknown:'Por confirmar',exempt:'Posible exención: por verificar',skip:'No lo solicitarás ahora'};const next=v=>v==='complete'?'Antes de presentar: revisa edición, respuestas, anexos, firma y método de envío.':v==='filed'||v==='approved'?'Conserva el recibo o aviso y revisa qué se envió. No presentes un duplicado automáticamente.':v==='unknown'||v==='exempt'?'Confirma requisitos con las instrucciones y busca orientación si tienes dudas.':v==='skip'?'Puedes revisar este beneficio más adelante si existe una categoría aplicable.':'Abre el formulario vigente y reúne sus documentos antes de completarlo.';const card=(form,title,v,url,info,action='')=>`<article class="evidence-card"><span class="formtag">${labels[v]}</span><h2>${form} · ${title}</h2><p>${info}</p><h3>Tu siguiente paso</h3><p>${next(v)}</p><div class="actions">${ext(url,'Formulario e instrucciones')}${action}</div></article>`;let cards=card('I-130','Petición familiar',p.i130,'https://www.uscis.gov/i-130','Revisa estatus del peticionario y evidencia del vínculo familiar. La solicitud de residencia es una etapa distinta.',("<button "+guideBind("click",(function(){return function(event){startVisual('family')}})())+">Ver imágenes de la I-130 →</button>"));if(p.relationship==='spouse')cards+=card('I-130A','Información del cónyuge',p.i130a,'https://www.uscis.gov/i-130','Ten a mano el historial de domicilios, empleos y datos biográficos solicitados. Descarga el suplemento en la página oficial de I-130.');if(['adjust','consular'].includes(p.route))cards+=card('I-864','Patrocinio económico',p.support,'https://www.uscis.gov/i-864','Revisa la versión o exención aplicable. Prepara documentación fiscal e ingresos actuales; comprueba si necesitas un patrocinador conjunto o I-864A para un miembro del hogar.');if(p.route==='adjust')cards+=card('I-765','Permiso de trabajo',p.ead,'https://www.uscis.gov/i-765','Beneficio opcional. No se obtiene por completar o presentar solo una I-130. Revisa la categoría correspondiente al ajuste y la evidencia de I-485.');app.innerHTML=("<div class=\"toolreturn\"><span>Ruta familiar / Tus formularios</span><button "+guideBind("click",(function(){return function(event){familyQuestions()}})())+">Editar respuestas</button><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Ver mi mapa</button></div>"+(contextBar('Petición familiar','Tu preparación, según tus respuestas',2,2))+"<p>“Completado” refleja lo que indicaste; la guía no ha revisado ni recibido tus formularios.</p>"+(p.route==='adjust'?'<div class="reference-note"><b>I-485:</b> '+({prepare:'Aún no presentada. Confirma elegibilidad, disponibilidad de visa, jurisdicción y si procede presentación conjunta.',pending:'Pendiente según tu respuesta. Conserva el recibo para las solicitudes relacionadas cuando corresponda.',unknown:'La posibilidad de ajuste está por confirmar. Busca orientación antes de presentar.'}[p.i485])+'</div>':'')+(p.route==='unknown'?'<p class="reference-note">Tu ruta está por confirmar. No asumimos que necesitas I-864, I-485 o I-765 en este momento.</p>':'')+"<div class=\"doc-evidence-grid\">"+(cards)+"</div><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(){return function(event){startVisual('family')}})())+">Continuar con imágenes de la I-130 →</button><button "+guideBind("click",(function(){return function(event){detailedDocuments()}})())+">Consultar documentos del proceso</button></div>");app.scrollIntoView({block:'start'})}
const familyStart=chooseProcess;
chooseProcess=function(){const k=document.querySelector('#processChoice').value;if(k==='family'||(k==='adjust'&&document.querySelector('#categoryChoice')?.value==='family')){mapProcess=k;mapCategory=k==='adjust'?'family':'';if(k==='adjust'&&!familyPrep.route)familyPrep.route='adjust';familyQuestions();app.scrollIntoView({block:'start'});return}familyStart()};
const familyStage=mapStage;mapStage=function(i){if(i===1&&(mapProcess==='family'||(mapProcess==='adjust'&&mapCategory==='family'))){familyQuestions();app.scrollIntoView({block:'start'});return}familyStage(i)};

/* A completed lesson advances to the next module; the map remains optional. */
const flowVisualSeen=new Set();
function flowKey(){return mapProcess+':'+(branchTitle()||'')}
function flowFooter(label,action,description=''){document.querySelector('.flow-next')?.remove();app.insertAdjacentHTML('beforeend',("<section class=\"flow-next\"><div><span class=\"formtag\">SIGUIENTE PASO</span><h3>"+(label)+"</h3>"+(description?`<p>${description}</p>`:'')+"</div><button class=\"primary\" "+guideBind("click",guideActionByText(action))+">Continuar →</button></section>"))}
function flowOpen(i){mapStage(i);app.scrollIntoView({block:'start'})}
function completeVisualFlow(){flowVisualSeen.add(flowKey());saved['visual-'+mapProcess]=true;persist();flowOpen(2)}
const flowingNextSpot=nextVisualSpot;
nextVisualSpot=function(){const g=visualGuides[visualKey];if(visualPage===g.slides.length-1&&visualSpot===g.slides[visualPage].spots.length-1){completeVisualFlow();return}flowingNextSpot()};
const flowingVisual=renderVisual;
renderVisual=function(){flowingVisual();const g=visualGuides[visualKey];if(visualPage===g.slides.length-1&&visualSpot===g.slides[visualPage].spots.length-1){document.querySelector('.visual-explanation button.primary').textContent='Continuar con mis documentos →'}};
const flowingEad=renderEadLesson;
renderEadLesson=function(){flowingEad();if(eduScreen===eadLessons.length-1){const b=document.querySelector('.lesson-footer button:last-child');b.textContent='Continuar con documentos →';b.setAttribute('onclick','completeVisualFlow()')}};
const flowingDocs=detailedDocuments;
detailedDocuments=function(){const result=flowingDocs();if(result){flowFooter(flowVisualSeen.has(flowKey())?'Organiza tu carta e índice':'Continúa con la guía visual',flowVisualSeen.has(flowKey())?'flowOpen(4)':'flowOpen(3)',flowVisualSeen.has(flowKey())?'Ya recorriste las imágenes. Ahora organiza los anexos que correspondan.':'Después de revisar los documentos, sigue las imágenes de tu proceso.');app.scrollIntoView({block:'start'})}return result};
const flowingPacket=packet;
packet=function(){flowingPacket();flowFooter('Revisión antes de presentar','flowOpen(5)','Conserva tu borrador editado antes de continuar. La guía no lo envía por ti.');app.scrollIntoView({block:'start'})};
const flowingEadPacket=eadPacket;
eadPacket=function(){flowingEadPacket();flowFooter('Revisión antes de presentar','flowOpen(5)','Descarga tu carta e índice si quieres conservar los cambios.');app.scrollIntoView({block:'start'})};
const flowingEadReview=eadFinalReview;
eadFinalReview=function(){flowingEadReview();const old=[...app.querySelectorAll('button')].find(b=>b.textContent.includes('Preparar carta e índice'));old?.remove();flowFooter('Termina este recorrido educativo','finishContinuousFlow()','Revisa cada punto que corresponda a tu situación.');app.scrollIntoView({block:'start'})};
const flowingStage=mapStage;
mapStage=function(i){flowingStage(i);if(i===0)flowFooter('Revisa los formularios de tu ruta','flowOpen(1)');if(i===1&&!document.querySelector('#familyValidation'))flowFooter('Prepara los documentos','flowOpen(2)');if(i===2&&!document.querySelector('.flow-next'))flowFooter(flowVisualSeen.has(flowKey())?'Organiza tu expediente':'Continúa con las imágenes',flowVisualSeen.has(flowKey())?'flowOpen(4)':'flowOpen(3)');if(i===3&&!visualGuides[mapProcess]&&!document.querySelector('.lesson-footer'))flowFooter('Organiza tu expediente','flowOpen(4)','Este paso no tiene más capturas verificadas. Continúa con la organización de tu solicitud.');if(i===5&&!document.querySelector('.flow-next'))flowFooter('Termina este recorrido educativo','finishContinuousFlow()');app.scrollIntoView({block:'start'})};
const flowingPortal=renderFriendlyPortal;
renderFriendlyPortal=function(){flowingPortal();if(friendlyPortalStep===friendlyPortal[mapProcess].length-1){const b=document.querySelector('.lesson-card button.primary');b.textContent='Continuar con documentos →';b.setAttribute('onclick','completeVisualFlow()')}};
const flowingTourNext=nextTour;
nextTour=function(){if(tourStep===5){saved['tour-'+tourKey+'-'+tourStep]=true;persist();flowOpen(4)}else flowingTourNext()};
function finishContinuousFlow(){saved['educational-route-'+flowKey()]=true;persist();app.innerHTML=("<article class=\"flow-complete\"><span class=\"pill\">✓ RECORRIDO EDUCATIVO TERMINADO</span><h2>Ya recorriste tu guía de "+(tourData[mapProcess].title)+"</h2><p>Conserva tus borradores y documentos. Completar la guía no presenta tu solicitud, confirma elegibilidad ni sustituye la revisión de las instrucciones oficiales.</p><p>Antes de enviar, revisa edición, firmas, anexos, tarifa y destino. Busca ayuda de un abogado de inmigración o representante acreditado cuando tengas dudas.</p><div class=\"actions\">"+(ext(tourData[mapProcess].source,'Consultar instrucciones oficiales'))+"<button "+guideBind("click",(function(){return function(event){flowOpen(5)}})())+">Revisar la lista final</button><button "+guideBind("click",(function(){return function(event){processPicker()}})())+">Elegir otro trámite</button></div><details><summary>Consultar mi mapa</summary><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Abrir mapa del proceso</button></details></article>");app.scrollIntoView({block:'start'})}

/* Professional cover letter and separate enclosure index. No personal data is saved. */
let formalItems=[],formalSelected=new Set();
const coverEnglish={'Prueba de que presentaste asilo':'Evidence of filing Form I-589','Identidad o permiso anterior':'Identity document or previously issued Employment Authorization Document','Fotografía para I-765':'Passport-style photographs, as required by the filing method','Traducciones':'Complete certified English translations','Registro de entrada o documento de viaje':'Arrival record or travel document, as applicable','EAD y motivo de renovación o reemplazo':'Prior Employment Authorization Document and renewal or replacement evidence','Antecedentes o cambios que afecten la solicitud':'Applicable court records or legal name-change documentation','Identidad y entradas':'Identity and immigration entry records','Familiares incluidos':'Civil records for included family members','Hechos y pruebas del caso':'Evidence supporting the facts of the asylum claim','Condiciones del país':'Relevant country-condition evidence','Identidad y nacimiento':'Identity document and birth record','Entrada y base del ajuste':'Entry records and evidence of the adjustment category','Patrocinio económico':'Applicable Affidavit of Support and financial evidence','Examen médico':'Form I-693, as applicable','Residencia e identidad':'Permanent resident and identity records','Historial de viajes':'Travel history and supporting records','Documentos condicionales':'Additional records applicable to the naturalization application'};
function coverItems(){const k=mapProcess,t=tourData[k];if(k==='family'||(k==='adjust'&&mapCategory==='family')){const p=familyPrep;let a=[['Form I-130, Petition for Alien Relative','Solo si este envío incluye una petición nueva. Si ya fue presentada, identifica el recibo como evidencia cuando corresponda.'],['Evidence of the petitioner’s citizenship or lawful permanent resident status','Identifica el documento concreto que realmente incluirás.'],['Civil records establishing the qualifying family relationship','Actas pertinentes y terminación de matrimonios anteriores cuando aplique.']];if(p.relationship==='spouse')a.splice(1,0,['Form I-130A, Supplemental Information for Spouse Beneficiary','Para petición conyugal, cuando corresponda a este envío.']);if(p.route==='adjust'||k==='adjust')a.push(['Form I-485, Application to Register Permanent Residence or Adjust Status','Solo si se presenta en este paquete y procede según la ruta.'],['Form I-864 or applicable Affidavit of Support, with financial evidence','Identifica formulario, patrocinador y documentos fiscales/de ingresos pertinentes.'],['Form I-693, Report of Immigration Medical Examination and Vaccination Record','Solo si corresponde; sigue las instrucciones de preparación y manejo del documento.'],['Form I-765, Application for Employment Authorization','Opcional y según categoría. No lo incluyas como requisito automático de I-130.']);a.push(['Certified English translations of foreign-language records','Identifica cada documento original y su traducción completa.']);return a}const docs=k==='ead'?eadDocuments():evidenceDetails[k];return [[t.form,'Especifica el formulario exacto que se incluye y comprueba la edición aceptada.'],...(docs||t.docs.map(x=>({title:x,check:'Describe el documento exacto que realmente incluyes.'}))).map(d=>[d.title,d.check||'Identifica los documentos y páginas que se incluyen.'])]}
function coverSubject(){const k=mapProcess;if(k==='family')return 'Form I-130 — Petition for Alien Relative';if(k==='adjust')return 'Form I-485 — Application to Register Permanent Residence or Adjust Status';if(k==='ead')return 'Form I-765 — Application for Employment Authorization';if(k==='asylum')return 'Form I-589 — Application for Asylum and for Withholding of Removal';return tourData[k].form}
function formalBody(){const family=mapProcess==='family',agency=(mapProcess==='court'||(mapProcess==='asylum'&&mapCategory==='court'))?'Executive Office for Immigration Review':'U.S. Citizenship and Immigration Services';return `[DATE]\n\n${agency}\n[VERIFIED FILING ADDRESS / OFFICE, IF APPLICABLE]\n\nRE: ${coverSubject()}\n${family?'Petitioner: [FULL LEGAL NAME]\nBeneficiary: [FULL LEGAL NAME]':'Applicant: [FULL LEGAL NAME]'}\n[RECEIPT NUMBER / A-NUMBER, ONLY IF ASSIGNED AND RELEVANT]\n\nDear Sir or Madam:\n\nPlease find enclosed the ${family?'petition':'application or request'} identified above, together with the supporting documents listed in the attached Index of Enclosures.\n\n[Briefly identify the purpose of this submission. State whether this is an initial filing or a submission related to an existing matter. Include only accurate facts relevant to this filing.]\n\nThe enclosed materials are organized in the order shown in the index. [Identify any related filings or prior receipt notices only if relevant to this submission.]\n\n[If an explanation is necessary, describe the specific document or issue and identify the supporting enclosure. Delete this paragraph if it does not apply.]\n\nThank you for your consideration of this submission.\n\nRespectfully submitted,\n\n[SIGNATURE, IF APPLICABLE]\n[FULL LEGAL NAME]\n[ROLE: PETITIONER / APPLICANT, AS APPLICABLE]\n[MAILING ADDRESS]\n[CONTACT INFORMATION, IF APPROPRIATE]`}
function formalCover(){if(!mapProcess)return processPicker();formalItems=coverItems();formalSelected=new Set();app.innerHTML=("<div class=\"toolreturn\"><span>"+(tourData[mapProcess].title)+" / Carta de presentación</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Consultar mi mapa</button></div>"+(contextBar(tourData[mapProcess].title,'Prepara una carta formal y un índice claro',5,6))+"<section class=\"cover-intro\"><span class=\"formtag\">CARTA DE PRESENTACIÓN · COVER LETTER</span><h2>Presenta tu expediente con orden y claridad</h2><p>Una carta breve identifica qué envías y un índice permite encontrar cada anexo. Esta plantilla no sustituye formularios, evidencia ni instrucciones de presentación.</p></section><div class=\"cover-guide\"><article><b>1. Identifica el envío</b><p>Confirma el trámite, si es inicial o relacionado con un caso existente, y el destinatario correcto. No uses la dirección de un ejemplo.</p></article><article><b>2. Enumera lo que incluyes</b><p>Marca solo formularios y documentos que realmente irán en este envío. Describe cada anexo; elimina los que no correspondan.</p></article><article><b>3. Revisa y conserva</b><p>Quita todos los marcadores entre corchetes, contrasta el índice con el paquete y guarda una copia completa.</p></article></div><p class=\"reference-note\">Trabaja aquí con marcadores, sin ingresar datos personales. La carta está en inglés y es editable. Para presentación en línea, usa los apartados que indique el portal; esta carta o un paquete único no son obligatorios por defecto. Verifica requisitos de notificación o entrega de copias si tu trámite los exige.</p><section class=\"cover-editor\"><h2>A. Selecciona los anexos de este envío</h2><p>Las opciones son una ayuda de organización, no una lista de requisitos confirmados.</p>"+(formalItems.map(([name,tip],i)=>("<label class=\"cover-item\"><input type=\"checkbox\" "+guideBind("change",(function(arg0,arg1){return function(event){if(this.checked)formalSelected.add(arg0);else formalSelected.delete(arg1);updateFormalIndex()}})(i,i))+"><span><b>"+(name)+"</b><small>"+(tip)+"</small></span></label>")).join(''))+"<h2>B. Adapta la carta</h2><p>Reemplaza los marcadores en tu copia final. No afirmes elegibilidad ni incluyas hechos que no puedas confirmar.</p><label for=\"formalBody\">Texto editable de la carta</label><textarea id=\"formalBody\" rows=\"23\" "+guideBind("input",(function(){return function(event){renderFormalPreview()}})())+">"+(esc(formalBody()))+"</textarea><h2>C. Revisa el índice</h2><p>Al marcar anexos se genera una base. Después puedes precisar documentos, fechas y páginas. Si cambias las selecciones, se reconstruye el índice.</p><label for=\"formalIndex\">Índice editable de anexos</label><textarea id=\"formalIndex\" rows=\"10\" "+guideBind("input",(function(){return function(event){renderFormalPreview()}})())+">INDEX OF ENCLOSURES\n\n[Select the documents actually included in this submission, then specify each enclosure.]</textarea><div class=\"cover-review-note\"><b>Antes de imprimir:</b> confirma nombres y números, propósito, destinatario, firmas aplicables, traducciones y correspondencia exacta entre el índice y los documentos. Revisa tarifas y forma de presentación en la fuente oficial.</div><div class=\"actions\"><button class=\"primary\" "+guideBind("click",(function(){return function(event){printFormalCover()}})())+">Imprimir o guardar como PDF</button><button "+guideBind("click",(function(){return function(event){downloadFormalCover()}})())+">Descargar texto editable</button>"+(ext(tourData[mapProcess].source,'Instrucciones oficiales de mi trámite'))+"</div><p id=\"formalPrintHint\" role=\"status\"></p></section><section class=\"cover-preview-title\"><h2>Vista previa del documento</h2><p>La impresión muestra únicamente la carta y el índice, sin botones ni elementos de la página.</p></section><div id=\"formalPrint\"><article class=\"letter-paper\"><div class=\"letter-rule\"></div><pre id=\"formalBodyPreview\"></pre></article><article class=\"letter-paper index-paper\"><div class=\"letter-rule\"></div><pre id=\"formalIndexPreview\"></pre></article></div>");renderFormalPreview();flowFooter('Continúa con la revisión final','flowOpen(5)','Descarga o imprime tu copia antes de avanzar. Este texto no se guarda al salir.');app.scrollIntoView({block:'start'})}
function updateFormalIndex(){document.querySelector('#formalIndex').value='INDEX OF ENCLOSURES\n\nRE: '+coverSubject()+'\n[PETITIONER / APPLICANT NAME]\n\n'+(formalSelected.size?[...formalSelected].sort((a,b)=>a-b).map((i,n)=>`${n+1}. ${coverEnglish[formalItems[i][0]]||formalItems[i][0]}\n   [Identify the actual documents, dates, and pages included.]`).join('\n\n'):'[Select only the documents actually included in this submission.]');renderFormalPreview()}
function renderFormalPreview(){document.querySelector('#formalBodyPreview').textContent=document.querySelector('#formalBody').value;document.querySelector('#formalIndexPreview').textContent=document.querySelector('#formalIndex').value}
function printFormalCover(){document.querySelector('#formalPrintHint').textContent='En el diálogo de impresión, selecciona “Guardar como PDF” si necesitas un archivo. Antes de usarlo, reemplaza todos los marcadores en tu copia final.';window.print()}
function downloadFormalCover(){const body=document.querySelector('#formalBody').value+'\n\n\n'+document.querySelector('#formalIndex').value;const u=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='cover-letter-'+mapProcess+'-index.txt';a.click();URL.revokeObjectURL(u)}
packet=formalCover;eadPacket=formalCover;

/* Educational worksheets. Draft text stays in page memory; no upload or AI evaluation. */
let asylumStoryReviewed=false;
let asylumEventCount=2,asylumWorksheet='',asylumNarrativeText='';
const asylumSources={instructions:'https://www.uscis.gov/sites/default/files/document/forms/i-589instr.pdf',overview:'https://www.justice.gov/eoir/asylum-withholding-removal-convention-against-torture'};
function eventWorksheet(n){return `EVENTO E${String(n).padStart(2,'0')}\nFecha: [fecha exacta o aproximada, identificada como aproximada]\nLugar: [ciudad y lugar específico que recuerdes]\nQué ocurrió: [describe hechos en orden, sin agregar detalles que no recuerdes]\nQuién actuó y cómo lo sabes: [personas o grupo; distingue lo que viste de lo que te contaron]\nQué dijeron o hicieron: [palabras que recuerdes; no uses comillas si no recuerdas la expresión exacta]\nPor qué crees que te dirigieron ese daño o amenaza: [hechos, palabras o contexto que sustentan tu explicación]\nQué consecuencias tuvo: [lesiones, amenazas, cambios en tu vida u otras consecuencias reales]\nQué hiciste después y qué respuesta recibiste: [ayuda buscada, denuncia, atención u otras acciones, si ocurrieron]\nQuién lo presenció o te informó: [identifica la fuente y qué conoce directamente]\nEvidencia relacionada: [Anexo A-01, etc., si existe]\nQué no recuerdas o no puedes documentar: [explica con precisión, sin completar con suposiciones]`}
const narrativeOutline=`GUÍA PARA PREPARAR MI RELATO PERSONAL — ASILO\n\nEste es un esquema de trabajo. No es un testimonio terminado ni una evaluación de elegibilidad. Utiliza solo hechos reales y revisa la versión final antes de firmar o presentar.\n\n1. CONTEXTO PERSONAL\n[Explica quién eres y el contexto necesario para entender tu historia. No incluyas datos o actividades que no sean tuyos.]\n\n2. RAZONES POR LAS QUE SOLICITO PROTECCIÓN\n[Describe quién te dañó o quién temes que te dañe, qué temes y por qué crees que se relaciona contigo. Distingue hechos conocidos, información de terceros y conclusiones.]\n\n3. MIS EVENTOS EN ORDEN CRONOLÓGICO\n[Transforma cada evento de tu cronología en uno o más párrafos en primera persona. Incluye fecha, lugar, lo ocurrido y consecuencias. Mantén los identificadores E01, E02 para organizar el borrador.]\n\n4. BÚSQUEDA DE AYUDA Y RESPUESTA\n[Si buscaste protección o asistencia, explica qué hiciste y qué ocurrió. Si no lo hiciste, explica tus razones reales. No inventes una denuncia.]\n\n5. CAMBIOS DE RESIDENCIA Y SALIDA\n[Explica los cambios, desplazamientos o salida que sean pertinentes. Si hay razones por las que no podrías estar a salvo en otra parte de tu país, describe los hechos que conoces.]\n\n6. POR QUÉ TEMO REGRESAR AHORA\n[Explica el riesgo actual que temes y los hechos que sustentan ese temor. Incluye información posterior a tu salida si la conoces e identifica su fuente. No es necesario inventar daños pasados para hablar de temor futuro.]\n\n7. EVIDENCIAS Y FALTANTES\n[Relaciona los párrafos o eventos con los anexos que realmente tengas. Explica qué prueba no está razonablemente disponible y por qué.]\n\n8. REVISIÓN FINAL\n[Compara nombres, fechas, entradas y hechos con tu I-589 y declaraciones previas. Explica diferencias reales; no cambies hechos para aparentar consistencia. Revisa idioma, traducción, identificación y firma de las hojas complementarias según las instrucciones vigentes.]`;
function captureAsylumDraft(){const a=document.querySelector('#asylumChronology');if(a)asylumWorksheet=a.value;const b=document.querySelector('#asylumNarrative');if(b)asylumNarrativeText=b.value}
function asylumStory(){document.body.classList.add('in-lesson');if(!asylumWorksheet)asylumWorksheet=[eventWorksheet(1),eventWorksheet(2)].join('\n\n');if(!asylumNarrativeText)asylumNarrativeText=narrativeOutline;app.innerHTML=("<div class=\"toolreturn\"><span>Asilo / Relato y cronología</span><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Consultar mi mapa</button></div>"+(contextBar('Solicitud de asilo · I-589','Organiza tu relato personal',1,2))+"<article class=\"story-intro\"><span class=\"formtag\">TU HISTORIA · EN TUS PALABRAS</span><h2>¿Qué ocurrió, cuándo y por qué pides protección?</h2><p>El formulario necesita respuestas sobre tu caso. El relato permite explicar los hechos con orden y detalle, y las evidencias ayudan a sustentarlos. Una cronología es una herramienta de trabajo; no reemplaza la I-589 ni constituye un requisito de formato único.</p></article><div class=\"story-path\"><span>1 · Ordena los eventos</span><span>2 · Redacta en primera persona</span><span>3 · Vincula cada hecho con una prueba</span></div><section class=\"story-panel\"><h2>Primero: explica las razones de tu solicitud</h2><p>Describe el daño sufrido o el temor de daño futuro, quién lo causó o podría causarlo y los hechos que explican por qué te dirigieron ese daño. La ley contempla raza, religión, nacionalidad, opinión política o pertenencia a determinado grupo social. Describir una experiencia no confirma por sí solo que reúna los requisitos legales.</p><div class=\"story-prompts\"><article><b>Qué pasó o qué temes</b><p>Explica conductas, amenazas y consecuencias concretas. El temor futuro también requiere una explicación propia.</p></article><article><b>Por qué crees que ocurrió</b><p>Señala palabras, hechos o contexto que lo apoyan. No elijas una razón solo porque parezca favorecer tu solicitud.</p></article><article><b>Qué sabes y cómo lo sabes</b><p>Distingue lo que viviste de lo que otra persona te informó. Identifica la fuente y las dudas que mantengas.</p></article></div>"+(ext(asylumSources.overview,'Consultar explicación oficial de asilo'))+"</section><section class=\"story-panel\"><h2>A. Prepara una cronología de tus eventos</h2><p>Usa un bloque por evento, del más antiguo al más reciente. Si desconoces el día exacto, indica que la fecha es aproximada. No conviertas una estimación en una fecha exacta.</p><p class=\"reference-note\">Usa marcadores aquí y prepara tu versión con datos personales en una copia local. No subas pruebas ni escribas detalles sensibles en esta guía. El texto de trabajo no se guarda al salir ni se envía a una IA.</p><label for=\"asylumChronology\">Plantilla de cronología — E01, E02…</label><textarea id=\"asylumChronology\" rows=\"20\" "+guideBind("input",(function(){return function(event){captureAsylumDraft()}})())+">"+(esc(asylumWorksheet))+"</textarea><button "+guideBind("click",(function(){return function(event){addAsylumEvent()}})())+">+ Agregar otro bloque de evento</button><aside class=\"story-example\"><b>Conexión de trabajo:</b> Evento E01 → párrafo correspondiente del relato → Anexo A-01, si existe. Un mismo documento puede relacionarse con varios eventos; explica qué parte respalda cada uno.</aside></section><section class=\"story-panel\"><h2>B. Convierte la cronología en tu testimonio o relato</h2><p>Redacta en primera persona y con tus palabras. No copies historias de otras personas ni pidas a una IA que añada hechos. Este esquema te ayuda a organizar la explicación; no genera un relato verdadero por ti.</p><label for=\"asylumNarrative\">Esquema editable del relato personal</label><textarea id=\"asylumNarrative\" rows=\"20\" "+guideBind("input",(function(){return function(event){captureAsylumDraft()}})())+">"+(esc(asylumNarrativeText))+"</textarea><div class=\"actions\"><button "+guideBind("click",(function(){return function(event){downloadAsylumWorksheet()}})())+">Descargar guía de relato y cronología</button>"+(ext(asylumSources.instructions,'Ver instrucciones de I-589'))+"</div><p>Antes de presentar, revisa las instrucciones de hojas adicionales, idioma, traducciones y firmas. Consulta a un abogado o representante acreditado sobre los requisitos y tu situación.</p></section>");flowFooter('Relaciona tu historia con las evidencias','captureAsylumDraft();asylumEvidence()','Ahora revisaremos qué documentos podrían respaldar los hechos que describes.');app.scrollIntoView({block:'start'})}
const asylumEvidenceRows=[
['Amenazas o comunicaciones','Mensajes completos, correos, cartas o registros de llamadas que existan.','Tus archivos y dispositivos; conserva los originales disponibles.','Fecha, emisor, destinatario, contexto y relación con el evento. Una captura aislada puede omitir información importante.'],
['Lesiones y consecuencias','Expedientes médicos o psicológicos, constancias de atención y fotografías pertinentes.','Institución que atendió o profesional que evaluó realmente.','Qué registra el documento y cuándo; no lo presentes como prueba de aspectos que no confirma.'],
['Hechos denunciados o actuaciones oficiales','Copia de denuncia, citación, acta, resolución u otro documento oficial que realmente exista.','Autoridad emisora, expediente o copia conservada.','Fecha, autoridad, contenido y respuesta recibida. Si no denunciaste, explica por qué; no inventes una denuncia.'],
['Testigos de hechos concretos','Declaración de quien presenció o conoce directamente un hecho pertinente.','La propia persona que aporta el testimonio.','Qué sabe, cómo lo sabe y qué parte conoció por terceros. Que use sus palabras y hechos reales.'],
['Actividad, identidad o contexto vinculado al motivo','Registros de participación, documentos, publicaciones o comunicaciones auténticas pertinentes a tu historia.','Organización emisora o tus archivos originales disponibles.','Cómo se relacionan con el motivo que describes; poseer un documento no demuestra por sí solo todos los requisitos de asilo.'],
['Condiciones del país y riesgo actual','Informes oficiales, de organismos y noticias verificables pertinentes al lugar, periodo y problema que describes.','Publicación original con autor, fecha y enlace.','Qué pasaje es relevante y por qué. Los informes generales contextualizan; no sustituyen los hechos personales.']
];
function asylumEvidence(){app.innerHTML=("<div class=\"toolreturn\"><span>Asilo / Evidencias de tus razones</span><button "+guideBind("click",(function(){return function(event){asylumStory()}})())+">Revisar mi esquema</button><button "+guideBind("click",(function(){return function(event){mapView()}})())+">Consultar mi mapa</button></div>"+(contextBar('Solicitud de asilo · I-589','Conecta hechos, razones y evidencias',2,2))+"<h2>¿Qué puede respaldar cada parte de tu historia?</h2><p>USCIS pide corroboración razonablemente disponible de los hechos y del contexto del país. Estos son ejemplos, no una lista que todas las personas deban reunir completa. Si una prueba no está razonablemente disponible, explica por qué. No te pongas en riesgo para conseguirla.</p><div class=\"doc-evidence-grid\">"+(asylumEvidenceRows.map((r,i)=>`<article class="evidence-card"><span class="formtag">EVIDENCIA · ${i+1}</span><h2>${r[0]}</h2><h3>Qué puedes utilizar</h3><p>${r[1]}</p><dl><dt>Dónde buscarlo</dt><dd>${r[2]}</dd><dt>Qué revisar</dt><dd>${r[3]}</dd><dt>Cómo relacionarlo</dt><dd>Indica el evento E01, E02… y el párrafo del relato que ayuda a respaldar. No atribuyas al documento más de lo que muestra.</dd></dl></article>`).join(''))+"</div><section class=\"story-panel\"><h2>Construye una tabla de evidencias</h2><div class=\"story-table-wrap\"><table class=\"story-table\"><thead><tr><th>Evento</th><th>Anexo</th><th>Documento</th><th>Qué respalda</th><th>Si falta</th></tr></thead><tbody><tr><td>E01</td><td>A-01</td><td>[Título, emisor, fecha y páginas]</td><td>[Hecho o motivo concreto]</td><td>[Disponibilidad y explicación real]</td></tr></tbody></table></div><p>Es una estructura de organización, no un ejemplo de hechos reales. Numera únicamente los anexos que efectivamente tengas e identifica los pasajes relevantes.</p><h3>Si falta una prueba</h3><p>Describe qué documento sería, por qué no está disponible y las gestiones razonables que hiciste, si las hiciste. Distingue “no existe”, “no pude obtenerlo” y “no sé si existe”.</p><h3>Antes de adjuntar</h3><p>Revisa legibilidad, contexto, fechas y traducciones completas con su certificación cuando correspondan. Compara los documentos con el relato y la I-589; explica diferencias reales.</p><div class=\"actions\"><button "+guideBind("click",(function(){return function(event){downloadAsylumEvidence()}})())+">Descargar tabla y lista de evidencias</button>"+(ext(asylumSources.instructions,'Instrucciones oficiales de evidencia'))+"</div></section>");flowFooter('Revisa el resto de documentos del proceso','showAsylumDocumentChecklist()','Después podrás preparar la carta e índice y continuar a la revisión final.');app.scrollIntoView({block:'start'})}
function downloadAsylumText(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
function downloadAsylumWorksheet(){captureAsylumDraft();downloadAsylumText('asilo-guia-relato-cronologia.txt',asylumNarrativeText+'\n\nCRONOLOGÍA DE TRABAJO\n\n'+asylumWorksheet)}
function downloadAsylumEvidence(){downloadAsylumText('asilo-tabla-evidencias.txt','TABLA DE EVIDENCIAS — PLANTILLA\n\nEvento | Anexo | Documento, fecha y páginas | Hecho que respalda | Disponibilidad / explicación\nE01 | A-01 | [documento] | [hecho concreto] | [si falta, explicar]\n\n'+asylumEvidenceRows.map(r=>r.join('\n')).join('\n\n'))}
const asylumPreviousDocuments=detailedDocuments;
function showAsylumDocumentChecklist(){asylumStoryReviewed=true;asylumPreviousDocuments();app.scrollIntoView({block:'start'})}
detailedDocuments=function(){if(mapProcess==='asylum'&&!asylumStoryReviewed){asylumStory();return true}return asylumPreviousDocuments()};
const asylumOriginalCoverItems=coverItems;
coverItems=function(){const a=asylumOriginalCoverItems();if(mapProcess==='asylum')a.splice(1,0,['Personal statement / declaration and supporting chronology, if included','Incluye únicamente tu relato real revisado y los documentos que correspondan. La cronología es una herramienta de organización.']);return a};

function addAsylumEvent(){captureAsylumDraft();asylumEventCount++;asylumWorksheet+="\n\n"+eventWorksheet(asylumEventCount);asylumStory()}

